-- ---- M205-01 · Projektregistrierung und Anlagenkontext ----
-- ew_anschlussgroesse
update public.fields set verification_status='verified_against_standard', verification_quote='In Deutschland wurden in den letzten Jahren bei einer Reihe von kommunalen Kläranlagen mit Ausbaugrößen von ca. 100 EW bis 1.000.000 EW Anlagen zur Desinfektion des Kläranlagenablaufes nachgerüstet. Hierzu liegen mittlerweile belastbare Praxiserfahrungen vor. — printed p.7', verification_note='md-verified 2026-09-05 (Einleitung, printed p.7) [VC]', verified_at=now() where id='ca05205b-3d89-42e2-b867-5e3de172ca5c' and verification_status not in ('verified_against_standard','corrected');
-- biologische_vorbehandlung
update public.fields set verification_status='verified_against_standard', verification_quote='Das Merkblatt gibt Hinweise zu Auswahl, Planung, Bau und Betrieb von Anlagen, die der Desinfektion von kommunalem Abwasser nach biologischer Behandlung dienen. — printed p.8', verification_note='md-verified 2026-09-05 (§1, printed p.8) [VC]', verified_at=now() where id='a1444cf4-4b7f-4843-ba0d-adc79bc0dc3a' and verification_status not in ('verified_against_standard','corrected');
-- empfangsgewaesser_zweck
update public.fields set verification_status='verified_against_standard', verification_quote='Die mögliche Gefährdung, die von nicht desinfiziertem Abwasser ausgeht, ist abhängig von der Art der Nutzung des aufbereiteten Abwassers bzw. des Gewässers, in das eingeleitet wird. Bei Kläranlageneinleitungen in Oberflächengewässer ist zu beachten, dass durch die Desinfektion von Abwasser die diffusen Belastungen im Gewässer nicht erfasst werden können. — printed p.7', verification_note='md-verified 2026-09-05 (Einleitung, printed p.7) [VC] — free-text field; the guideline names the use classes in §3.2–§3.5 (see nutzungsziel)', verified_at=now() where id='5467521a-3741-4ffd-9f34-a0e153fd1589' and verification_status not in ('verified_against_standard','corrected');

-- ---- M205-02 · Anwendungsbereich und Begriffe ----
-- badegewaesser_guete
update public.fields set verification_status='verified_against_standard', verification_quote='Das Beurteilungssystem wurde in der aktuellen Badegewässerrichtlinie 2006/7/EG neu definiert (Tabelle 2). Im Gegensatz zur bisherigen Konzeption mit Leit- und Grenzwerten stuft die neue Richtlinie einen Badeplatz erstmals ab 2011 nach vier Gütekategorien ein: ausgezeichnet/gut/ausreichend/mangelhaft. — printed p.10–11', verification_note='md-verified 2026-09-05 (§3.2, printed p.10–11) [VC]', verified_at=now() where id='fddd8a6b-4425-4bc3-87c0-f8cb8353eae4' and verification_status not in ('verified_against_standard','corrected');
-- eignungsklasse_bewaesserung
update public.fields set verification_status='verified_against_standard', verification_quote='Entsprechend definiert die DIN 19650 vier Eignungsklassen in Abhängigkeit von der Nutzung der Bewässerungsfläche (Gewächshaus- und Freilandkulturen, Sportplätze, Grünanlagen u. Ä.). Die Anforderungen an die hygienische Qualität des Bewässerungswassers sind umso strenger, je höher die mit der Nutzung verbundene Wahrscheinlichkeit einer Verbreitung von Krankheitserregern ist. | Tabelle 3: Eignungsklassen und Anwendungsbereiche von Bewässerungswasser gemäß der „Empfehlungen für die Untersuchung und Bewertung von Wasser zur Bewässerung von gärtnerischen und landwirtschaftlichen Fruchtarten in Thüringen" — printed p.11 / p.12', verification_note='md-verified 2026-09-05 (§3.3 + Tab. 3, printed p.11 / p.12) [VC]', verified_at=now() where id='ea4217c5-d8c2-42c0-8518-8c771994c18e' and verification_status not in ('verified_against_standard','corrected');
-- eg_badegewaesser_richtlinie
update public.fields set verification_status='verified_against_standard', verification_quote='Die Gütekriterien für die Badegewässerqualität wurden zunächst durch die Richtlinie 76/160/EWG (EG-Badegewässerrichtlinie alt) definiert (Tabelle 1). | Das Beurteilungssystem wurde in der aktuellen Badegewässerrichtlinie 2006/7/EG neu definiert (Tabelle 2). — printed p.9 / p.10–11', verification_note='md-verified 2026-09-05 (§3.2, printed p.9 / p.10–11) [VC]', verified_at=now() where id='00a0b266-c05e-440f-9d4e-2c4efe8ea190' and verification_status not in ('verified_against_standard','corrected');
-- nutzungsziel
update public.fields set verification_status='verified_against_standard', verification_quote='Treibende Kraft für eine gezielte Desinfektion auf Kläranlagen war bisher im Regelfall die Verbesserung der hygienischen Qualität von Gewässern, die für Freizeitzwecke genutzt werden oder mit einer Trinkwassergewinnung in Verbindung stehen. Weitere Anwendungsbereiche ergeben sich bei der Aufbereitung von Teilströmen zu Betriebswasser. Wichtigstes Anwendungsgebiet der Abwasserdesinfektion in Ländern mit Wassermangel ist die Aufbereitung des kommunalen Abwassers zur Wiederverwendung, zum Beispiel zu Bewässerungszwecken. — printed p.7', verification_note='md-verified 2026-09-05 (Einleitung + §3.2–§3.5 headings, printed p.7 / p.9–13) [VC] — the four enum values mirror the §3.2 EG-Badegewässerrichtlinie / §3.3 Bewässerung / §3.4 Trinkwassergewinnung / §3.5 Brauchwassernutzung headings', verified_at=now() where id='750451b9-53c0-4955-9704-a962395100bb' and verification_status not in ('verified_against_standard','corrected');
-- behoerdliche_freigabe
update public.fields set verification_status='verified_against_standard', verification_quote='Die Festlegung des Behandlungsziels für die Abwasserdesinfektion erfolgt in der Regel durch die zuständige Behörde. Die Rahmenbedingungen für die Überprüfung dieser Zielvorgabe sind zu definieren: Zeitraum der Einhaltung (bei Badegewässern die Badesaison), Art der Probennahme und -behandlung, Bestimmungsverfahren für die zu untersuchenden Mikroorganismen, Auswertung der Ergebnisse, statistische Einhaltungsregeln. — printed p.8', verification_note='md-verified 2026-09-05 (§2.1 Anmerkung, printed p.8) [VC]', verified_at=now() where id='81b9d4ec-7863-437b-bf17-098129f29004' and verification_status not in ('verified_against_standard','corrected');
-- gewaesserklasse
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 2: Mikrobiologische Qualitätsanforderungen an Badegewässer nach der Richtlinie 2006/7/EG | Binnengewässer | Parameter & Ausgezeichnete Qualität & Gute Qualität & Ausreichende Qualität & Referenzanalysemethode | Küstengewässer und Übergangsgewässer | Die Werte in Klammern geben die Art der Perzentil-Bewertung an. — printed p.10', verification_note='md-verified 2026-09-05 (§3.2 Tab. 2, printed p.10) [VC] — enum has 5 of the 6 printed cells (Küste/ausreichend missing — STAGED)', verified_at=now() where id='5058689d-77c7-431b-bf86-ca0b1cb63040' and verification_status not in ('verified_against_standard','corrected');
-- toc_bewaesserung
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 3: Eignungsklassen und Anwendungsbereiche von Bewässerungswasser [...] Biologische Kenngrößen [...] TOC mg/l | 1 [...] ≤ 2 | 2 [...] ≤ 10 | 3 [...] 10 bis 20 | 4 [...] > 20 | 5) Wert, bei dessen Überschreitung der BSB5-Wert zu ermitteln ist. 6) Die 10-fache Menge sollte nicht überschritten werden. — printed p.12', verification_note='md-verified 2026-09-05 (§3.3 Tab. 3, printed p.12) [VC]', verified_at=now() where id='b971d5dc-a914-4236-83f5-71482ce288f7' and verification_status not in ('verified_against_standard','corrected');
-- daly_wert
update public.fields set verification_status='verified_against_standard', verification_quote='Die WHO geht von einem tolerierbaren DALY-Wert von 10⁻⁶ pro Person und Jahr aus, der nicht überschritten werden sollte. Auf dieser Grundlage werden in den Richtlinien Anforderungen an die Keimreduzierung abgeleitet, wobei Escherichia coli als Indikatorkeim dient. — printed p.11', verification_note='md-verified 2026-09-05 (§3.3, printed p.11) [VC]', verified_at=now() where id='1af2b69a-c282-43be-9477-a0360e0a605b' and verification_status not in ('verified_against_standard','corrected');
-- ziel_spurenstoffabbau
update public.fields set verification_status='verified_against_standard', verification_quote='Auch weitere Reinigungsziele (z. B. der Abbau von anthropogenen Spurenstoffen) können ausschlaggebend für die Verfahrenswahl sein. | Tabelle 8: Überblick über Desinfektionsverfahren [...] Zusätzliche Reinigungseffekte [...] Ozonung [...] Elimination anthropogener Spurenstoffe — printed p.31–32 / p.32', verification_note='md-verified 2026-09-05 (§5 + Tab. 8, printed p.31–32 / p.32) [VC]', verified_at=now() where id='e6427f32-6ba8-426a-8b08-43362de75da1' and verification_status not in ('verified_against_standard','corrected');
-- ziel_brauchwasser_oder_vollentkeimung
update public.fields set verification_status='verified_against_standard', verification_quote='Die nachgeschaltete Membrandesinfektion wurde bisher nur bei wenigen Kläranlagen großtechnisch betrieben bzw. erprobt, um den gesamten Kläranlagenablauf aufgrund besonderer gewässergütewirtschaftlicher Anforderungen oder einen Teilstrom zur Brauchwasseraufbereitung zu desinfizieren [23;24;27]. — printed p.22', verification_note='md-verified 2026-09-05 (§4.2.1, printed p.22) [VC]', verified_at=now() where id='972a4a0e-ca5e-4c8b-98aa-9bc032dd7973' and verification_status not in ('verified_against_standard','corrected');
-- brauchwasser_standzeit_h
update public.fields set verification_status='verified_against_standard', verification_quote='Um die Bildung unerwünschter Gerüche, Beläge und Verschleimungen in Behältern und Rohrleitungen und ähnlich störende Effekte zu verhindern und zur Keimreduzierung kann eine Abwasserdesinfektion sinnvoll sein. Insbesondere bei längeren Standzeiten ist die Möglichkeit der Wiederverkeimung zu berücksichtigen. — printed p.13', verification_note='md-verified 2026-09-05 (§3.5, printed p.13) [VC] — no numeric hours printed; unit h is EKOWAI’s', verified_at=now() where id='b09881a6-5e60-4c5b-bece-aaa15ee23888' and verification_status not in ('verified_against_standard','corrected');

