update public.fields set verification_status='verified_against_standard', verification_quote='Als Maß für die UV-C-Durchlässigkeit wird im Abwasserbereich in der Regel die UV-Transmission in %/cm, gemessen bei 1 cm Schichtdicke und 254 nm Wellenlänge, angegeben. | Bei Transmissionswerten unter 55 % bis 50 % sollte zunächst die Ursache erkundet und nach Möglichkeit beseitigt werden. — printed p.14 / p.15', verification_note='md-verified 2026-09-05 (§4.1.1 + §4.1.2.2, printed p.14 / p.15) [VC]', verified_at=now() where id='6fdbe76e-7a85-4555-a56c-32968f5a4534' and verification_status not in ('verified_against_standard','corrected');
-- afs
update public.fields set verification_status='verified_against_standard', verification_quote='Das Abwasser sollte vor der Bestrahlung weitgehend biologisch gereinigt und luftblasenfrei sein sowie mit einer niedrigen Konzentration an abfiltrierbaren Stoffen der Bestrahlungsanlage zugeführt werden (< 20 mg/l, besser z. B. nach Filtration < 5 mg/l). Zumindest bei zu erwartenden abfiltrierbaren Stoffen in der Größenordnung von 10 mg/l bis 20 mg/l empfiehlt es sich zu überprüfen, ob für eine sichere Reduktion eine vorgeschaltete Abwasserfiltration erforderlich wird. — printed p.15', verification_note='md-verified 2026-09-05 (§4.1.2.2, printed p.15) [VC]', verified_at=now() where id='cf2980d6-488b-4046-ae93-4324d91aa21f' and verification_status not in ('verified_against_standard','corrected');
-- durchfluss_max
update public.fields set verification_status='verified_against_standard', verification_quote='Notwendige Parameter zur Auslegung einer UVBestrahlungsanlage sind die erforderliche UV-Dosis, der maximale Zufluss und die minimale Transmission. | Bei starken Durchfluss-Schwankungen, immer aber bei Durchflüssen über 1000 m³/h ist die Aufteilung des Gesamtdurchflusses auf parallel angeordnete Gerinne zweckmäßig. — printed p.16 / p.18', verification_note='md-verified 2026-09-05 (§4.1.2.3 + §4.1.3.2, printed p.16 / p.18) [VC]', verified_at=now() where id='d9f2248c-89fb-4e68-87e6-82b4c101b600' and verification_status not in ('verified_against_standard','corrected');
