-- desinfektion_erforderlich
update public.fields set verification_status='verified_against_standard', verification_quote='Ob die nachgeschaltete Desinfektion von Kläranlagenabläufen ein praktikabler Weg zur Verbesserung der hygienischen Situation eines Gewässerabschnittes ist, muss durch eine systematische Untersuchung des Einzugsgebietes ermittelt werden (siehe Anhang A). | Die Notwendigkeit der Abwasserdesinfektion hängt entscheidend von der Nutzung des Gewässers ab, in welches das Abwasser eingeleitet wird bzw. von der Wiederverwendung des gereinigten Abwassers. — printed p.9 / p.31', verification_note='md-verified 2026-09-05 (§3.1 + §5, printed p.9 / p.31) [VC]', verified_at=now() where id='1a0256b1-d4d5-4694-af63-47d57d6a5306' and verification_status not in ('verified_against_standard','corrected');
-- quellen_punkt_diffus
update public.fields set verification_status='verified_against_standard', verification_quote='Hygienische Belastungen stammen aus aktuellen Einträgen im Einzugsgebiet. Sie können punktförmig erfolgen als Abwassereinleitungen aus kommunalen Kläranlagen und Entlastungsbauwerken von Mischwasserkanalisationen sowie als Niederschlagswassereinleitungen aus Trennkanalisationen. [...] Diffuse Einträge entstehen durch breitflächige Abschwemmungen von landwirtschaftlichen Nutzflächen, aber auch von versiegelten Siedlungsflächen und Straßen (Tierkot). — printed p.9', verification_note='md-verified 2026-09-05 (§3.1, printed p.9) [VC]', verified_at=now() where id='24cc05e1-b945-4d3b-a475-fb5291c2a890' and verification_status not in ('verified_against_standard','corrected');

-- ---- M205-04 · EG-Badegewässerrichtlinie ----
-- badegewaesser_guete
update public.fields set verification_status='verified_against_standard', verification_quote='Das Beurteilungssystem wurde in der aktuellen Badegewässerrichtlinie 2006/7/EG neu definiert (Tabelle 2). Im Gegensatz zur bisherigen Konzeption mit Leit- und Grenzwerten stuft die neue Richtlinie einen Badeplatz erstmals ab 2011 nach vier Gütekategorien ein: ausgezeichnet/gut/ausreichend/mangelhaft. — printed p.10–11', verification_note='md-verified 2026-09-05 (§3.2, printed p.10–11) [VC]', verified_at=now() where id='43bcd242-e4ae-427c-a84d-f14d2ef540c2' and verification_status not in ('verified_against_standard','corrected');
-- eg_badegewaesser_richtlinie
update public.fields set verification_status='verified_against_standard', verification_quote='Die Gütekriterien für die Badegewässerqualität wurden zunächst durch die Richtlinie 76/160/EWG (EG-Badegewässerrichtlinie alt) definiert (Tabelle 1). | Das Beurteilungssystem wurde in der aktuellen Badegewässerrichtlinie 2006/7/EG neu definiert (Tabelle 2). — printed p.9 / p.10–11', verification_note='md-verified 2026-09-05 (§3.2, printed p.9 / p.10–11) [VC]', verified_at=now() where id='14bb6ca9-b203-4361-9bbe-90a2ce3e8ebc' and verification_status not in ('verified_against_standard','corrected');
