-- ---- M205-05 · Bewässerung mit gereinigtem Abwasser ----
-- eignungsklasse_bewaesserung
update public.fields set verification_status='verified_against_standard', verification_quote='Entsprechend definiert die DIN 19650 vier Eignungsklassen in Abhängigkeit von der Nutzung der Bewässerungsfläche (Gewächshaus- und Freilandkulturen, Sportplätze, Grünanlagen u. Ä.). Die Anforderungen an die hygienische Qualität des Bewässerungswassers sind umso strenger, je höher die mit der Nutzung verbundene Wahrscheinlichkeit einer Verbreitung von Krankheitserregern ist. | Tabelle 3: Eignungsklassen und Anwendungsbereiche von Bewässerungswasser gemäß der „Empfehlungen für die Untersuchung und Bewertung von Wasser zur Bewässerung von gärtnerischen und landwirtschaftlichen Fruchtarten in Thüringen" — printed p.11 / p.12', verification_note='md-verified 2026-09-05 (§3.3 + Tab. 3, printed p.11 / p.12) [VC]', verified_at=now() where id='cc93375c-a332-4612-addc-175d605f4cc8' and verification_status not in ('verified_against_standard','corrected');
-- uv_dosis_zielband
update public.fields set verification_status='verified_against_standard', verification_quote='Danach beträgt die Mindestbestrahlung etwa 300 J/m² bis 450 J/m² zur sicheren Einhaltung der Grenz- und Leitwerte der EG-Badegewässer-Richtlinie für biologisch gereinigtes Abwasser bei einer Konzentration an abfiltrierbaren Stoffen von 5 mg/l bis 20 mg/l. | Entsprechend den Anforderungen kann die notwendige Mindestbestrahlung aber auch höher liegen. An der Isar wurde als Zielvorgabe die Unterschreitung der Leitwerte um eine Zehnerpotenz vorgegeben. Eine Auswertung der Daten von verschiedenen, im Betrieb befindlichen UVAnlagen zeigt eine Schwankungsbreite für die eingestellte Mindestbestrahlung von 400 J/m² bis 600 J/m² und im Einzelfall bis zu 700 J/m² [16]. — printed p.16', verification_note='md-verified 2026-09-05 (§4.1.2.3, printed p.16) [VC] — only two bands are printed; the third enum value „tab2_ausgezeichnet 400–700 J/m² (2006/7/EG)“ is not in the source (STAGED)', verified_at=now() where id='b4cb8163-a173-41f5-ac67-d3e72b685517' and verification_status not in ('verified_against_standard','corrected');
-- gerinne_abdeckung_lichtdicht
update public.fields set verification_status='verified_against_standard', verification_quote='Die offenen Gerinne sollten vollständig abgedeckt werden, um sie vor Lichteinfall zu schützen. Es kann sonst zu erhöhtem Algenwachstum im Gerinne kommen, das sich negativ auf die Leistungsfähigkeit der Anlage auswirkt. Eine lichtdichte Abdeckung der Gerinne über den Strahlern ist aus Gründen des Arbeitsschutzes erforderlich. — printed p.18', verification_note='md-verified 2026-09-05 (§4.1.3.2, printed p.18) [VC]', verified_at=now() where id='5ced6318-32ad-4e83-8564-1acc72689e47' and verification_status not in ('verified_against_standard','corrected');
-- ip_schutzart
update public.fields set verification_status='verified_against_standard', verification_quote='Alle elektrischen Einrichtungen und Verbindungen müssen gut zugänglich sein und den Einsatzbedingungen in nasser und feuchter Umgebung entsprechen. Sie sind in IP 54-67 auszuführen. Schaltanlagen sind ebenfalls vorzugsweise in IP 67 auszuführen oder spritzwassergeschützt aufzustellen. — printed p.18', verification_note='md-verified 2026-09-05 (§4.1.3.2, printed p.18) [VC]', verified_at=now() where id='fa0225a1-91f3-48cb-819b-a87fcb2893ee' and verification_status not in ('verified_against_standard','corrected');
-- invest_kosten_uv
update public.fields set verification_status='verified_against_standard', verification_quote='Die spezifischen Investitionskosten für UV-Anlagen gestalten sich tendenziell umso niedriger, je höher die Ausbaugröße ist (Bild 7), hängen jedoch im Einzelfall stark von den örtlichen Randbedingungen ab [...]. Die ermittelten Werte lagen zwischen 7 €/EW und 52 €/EW. Erhebliche zusätzliche Investitionskosten entstehen, wenn eine vorgeschaltete Filtration notwendig ist. — printed p.21', verification_note='md-verified 2026-09-05 (§4.1.5.1, printed p.21) [VC]', verified_at=now() where id='f740f1b2-96a7-40a4-a698-f346aea0473f' and verification_status not in ('verified_against_standard','corrected');
-- uv_dosis
update public.fields set verification_status='verified_against_standard', verification_quote='Die Anzahl der Treffer pro Zelle ist von der UV-Bestrahlung (UV-Dosis) in $\mathrm{J} / \mathrm{m}^{2}$ abhängig, die jede Zelle beim Durchgang durch den Bestrahlungsraum erhält (DIN 5031-1). | Danach beträgt die Mindestbestrahlung etwa 300 J/m² bis 450 J/m² zur sicheren Einhaltung der Grenz- und Leitwerte der EG-Badegewässer-Richtlinie für biologisch gereinigtes Abwasser [...] Eine Auswertung der Daten von verschiedenen, im Betrieb befindlichen UVAnlagen zeigt eine Schwankungsbreite für die eingestellte Mindestbestrahlung von 400 J/m² bis 600 J/m² und im Einzelfall bis zu 700 J/m² [16]. — printed p.14 / p.16', verification_note='md-verified 2026-09-05 (§4.1.1 + §4.1.2.3, printed p.14 / p.16) [VC]', verified_at=now() where id='6368dbb9-86f9-4b97-9131-481894855aea' and verification_status not in ('verified_against_standard','corrected');
-- uv_intensitaet
update public.fields set verification_status='verified_against_standard', verification_quote='Die UV-Bestrahlung, die eine Zelle im Mittel erhält, lässt sich rechnerisch als Produkt aus der mittleren Bestrahlungsstärke in $\mathrm{W} / \mathrm{m}^{2}$ und der mittleren Verweildauer in s abschätzen. Die Bestrahlungsstärke (Intensität) ist die pro Flächeneinheit ( $\mathrm{m}^{2}, \mathrm{~cm}^{2}$ ) auftreffende Strahlungsleistung ( $\mu \mathrm{W}, \mathrm{mW}, \mathrm{W}$ ). — printed p.14', verification_note='md-verified 2026-09-05 (§4.1.1, printed p.14) [VC]', verified_at=now() where id='a68ccda3-d609-4edf-8383-e4d204879dbb' and verification_status not in ('verified_against_standard','corrected');
-- verweildauer
update public.fields set verification_status='verified_against_standard', verification_quote='Die UV-Bestrahlung, die eine Zelle im Mittel erhält, lässt sich rechnerisch als Produkt aus der mittleren Bestrahlungsstärke in $\mathrm{W} / \mathrm{m}^{2}$ und der mittleren Verweildauer in s abschätzen. [...] Die Verweildauer ist die Zeit, die eine Zelle der UV-Strahlung ausgesetzt ist. — printed p.14', verification_note='md-verified 2026-09-05 (§4.1.1, printed p.14) [VC]', verified_at=now() where id='922e28c4-3aa8-4f77-a00b-a3226ca05305' and verification_status not in ('verified_against_standard','corrected');
-- uvt_min
update public.fields set verification_status='verified_against_standard', verification_quote='Notwendige Parameter zur Auslegung einer UVBestrahlungsanlage sind die erforderliche UV-Dosis, der maximale Zufluss und die minimale Transmission. [...] Die Bemessungsvorgaben dieser UV-Anlagen für die Transmission liegen im Bereich > 60 % bis > 70 % (in der Regel > 65 %) und für die abfiltrierbaren Stoffe bei < 10 mg/l bzw. zum Teil auch < 5 mg/l. — printed p.16', verification_note='md-verified 2026-09-05 (§4.1.2.3, printed p.16) [VC]', verified_at=now() where id='23f631fb-0ecf-4100-89bd-024570f7ac58' and verification_status not in ('verified_against_standard','corrected');
-- uvc_anteil
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 4: Merkmale und Eigenschaften von Niederdruck- und Mitteldruck-UV-Strahlern (Quelle: Technische Mitteilung 01/08 der figawa) | UV-C-Leistung ( 254 nm ) \% bezogen auf die eingespeiste elektr. Leistung bei neuem Strahler & \% & ca. 20-35 & ca. 8-15 — printed p.17', verification_note='md-verified 2026-09-05 (§4.1.3.1 Tab. 4, printed p.17) [VC]', verified_at=now() where id='add38d7b-231c-40b2-bcf3-b7c3922571a5' and verification_status not in ('verified_against_standard','corrected');
-- strahlertyp
update public.fields set verification_status='verified_against_standard', verification_quote='UV-Strahlung wird technisch in der Regel durch Nieder-druck- oder Mitteldruck-Quecksilberdampf-Entladungslampen erzeugt. Mitteldruckstrahler weisen aufgrund ihres breitbandigen Spektrums eine deutlich geringere Energieeffizienz auf, können aber aufgrund der höheren Leistungsdichte kompakter ausgeführt werden. Niederdruckstrahler haben bezogen auf den elektrischen Energieverbrauch eine hohe UV-C-Ausbeute. — printed p.16–17', verification_note='md-verified 2026-09-05 (§4.1.3.1, printed p.16–17) [VC]', verified_at=now() where id='ca21ef93-3943-409f-8065-8c7db4ef2d78' and verification_status not in ('verified_against_standard','corrected');
-- strahler_nutzungsdauer
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 4: Merkmale und Eigenschaften von Niederdruck- und Mitteldruck-UV-Strahlern [...] Mittlere Nutzungsdauer & h & 8.000-16.000 & 4.000-12.000 | Die garantierten Lebensdauern von UV-Strahlern liegen im Bereich von 8.000 bis 12.000 Betriebsstunden. | Sie sollten daher nach der vom Hersteller empfohlenen Nutzungsdauer ausgetauscht werden. — printed p.17 / p.22 / p.20', verification_note='md-verified 2026-09-05 (Tab. 4 + §4.1.5.2 + §4.1.4.4, printed p.17 / p.22 / p.20) [VC]', verified_at=now() where id='ee3b143a-fd96-4d8f-915e-4d5c0b563f06' and verification_status not in ('verified_against_standard','corrected');
-- strahler_oberflaechentemperatur
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 4: Merkmale und Eigenschaften von Niederdruck- und Mitteldruck-UV-Strahlern | Merkmal & Einheit & Niederdruckstrahler & Mitteldruckstrahler | Oberflächentemperatur Strahler & °C & 40-120 & 600-950 — printed p.17', verification_note='md-verified 2026-09-05 (§4.1.3.1 Tab. 4, printed p.17) [VC]', verified_at=now() where id='a3e19b87-48bb-4e2f-9892-ae03e3989151' and verification_status not in ('verified_against_standard','corrected');
-- strahler_quecksilberdampfdruck
