-- strahler_leistungsdichte
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 4: Merkmale und Eigenschaften von Niederdruck- und Mitteldruck-UV-Strahlern | Merkmal & Einheit & Niederdruckstrahler & Mitteldruckstrahler | Typische Leistungsdichte bezogen auf die Lichtbogenlänge & $\mathrm{W} / \mathrm{cm}$ & 1-4 & 100-200 — printed p.17', verification_note='md-verified 2026-09-05 (§4.1.3.1 Tab. 4, printed p.17) [VC]', verified_at=now() where id='97ccac0d-15a5-48b7-a0cc-ab792fcf6b3c' and verification_status not in ('verified_against_standard','corrected');
-- strahler_wellenlaenge
update public.fields set verification_status='verified_against_standard', verification_quote='UV-C & UV-Strahlung im Wellenbereich 100 nm bis 280 nm | Tabelle 4: Merkmale und Eigenschaften von Niederdruck- und Mitteldruck-UV-Strahlern [...] Wellenlänge im UV-C-Bereich & nm & 254 nm & 240 nm-280 nm — printed p.8 / p.17', verification_note='md-verified 2026-09-05 (§2.2 + Tab. 4, printed p.8 / p.17) [VC]', verified_at=now() where id='215025e0-5c04-4ce9-a3c6-09a67846f22b' and verification_status not in ('verified_against_standard','corrected');
-- spez_strom_uv
update public.fields set verification_status='verified_against_standard', verification_quote='Bei den ausgewerteten Desinfektionsanlagen bewegt sich der spezifische Stromverbrauch im Bereich von 30 Wh bis 60 Wh pro Kubikmeter behandelten Abwassers. — printed p.22', verification_note='md-verified 2026-09-05 (§4.1.5.2, printed p.22) [VC]', verified_at=now() where id='a0bfc02e-ed3e-482d-96c3-27543c8b4e30' and verification_status not in ('verified_against_standard','corrected');
-- kosten_uv_cent_m3
update public.fields set verification_status='verified_against_standard', verification_quote='Die spezifischen Kosten (jährliche Kapital- und Betriebskosten pro Kubikmeter desinfizierten Abwassers) bewegen sich bei den ausgewerteten Anlagen im Bereich von ca. 3 Cent/m³ bis 10 Cent/m³ für einen in etwa halbjährigen Betrieb. [...] Legt man einen ganzjährigen Betrieb zugrunde läge die Spannbreite der spezifischen Kosten bei rund 2 Cent/m³ bis 6 Cent/m³. — printed p.22', verification_note='md-verified 2026-09-05 (§4.1.5.3, printed p.22) [VC]', verified_at=now() where id='1a73ea97-10da-4333-9624-16443796bac6' and verification_status not in ('verified_against_standard','corrected');
-- toc_bewaesserung
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 3: Eignungsklassen und Anwendungsbereiche von Bewässerungswasser [...] Biologische Kenngrößen [...] TOC mg/l | 1 [...] ≤ 2 | 2 [...] ≤ 10 | 3 [...] 10 bis 20 | 4 [...] > 20 | 5) Wert, bei dessen Überschreitung der BSB5-Wert zu ermitteln ist. 6) Die 10-fache Menge sollte nicht überschritten werden. — printed p.12', verification_note='md-verified 2026-09-05 (§3.3 Tab. 3, printed p.12) [VC]', verified_at=now() where id='b9551350-38f3-48f0-958f-c8995508e5ee' and verification_status not in ('verified_against_standard','corrected');
-- daly_wert
update public.fields set verification_status='verified_against_standard', verification_quote='Die WHO geht von einem tolerierbaren DALY-Wert von 10⁻⁶ pro Person und Jahr aus, der nicht überschritten werden sollte. Auf dieser Grundlage werden in den Richtlinien Anforderungen an die Keimreduzierung abgeleitet, wobei Escherichia coli als Indikatorkeim dient. — printed p.11', verification_note='md-verified 2026-09-05 (§3.3, printed p.11) [VC]', verified_at=now() where id='c789e6af-8b38-4595-bff8-ad86a4929d41' and verification_status not in ('verified_against_standard','corrected');
-- nicht_bestrahltes_volumen
update public.fields set verification_status='verified_against_standard', verification_quote='Schon geringe Kurzschlussströmungen begrenzen die erreichbare Reduktionsleistung. Ein Prozent nicht bestrahltes Volumen reicht aus, um die maximale Reduktion auf zwei Log-Stufen zu begrenzen [7]. — printed p.14', verification_note='md-verified 2026-09-05 (§4.1.1, printed p.14) [VC]', verified_at=now() where id='7f2b04f1-828f-4435-9bdf-6e0dcc54efb4' and verification_status not in ('verified_against_standard','corrected');
-- strahler_auslastung_pct
update public.fields set verification_status='verified_against_standard', verification_quote='Die Strahlerauslastung (Laufzeit einzelner Banks im Verhältnis zur Gesamtbetriebszeit der Abwasserdesinfektion) der untersuchten Anlagen liegt in der Regel bei rund 50 % bis 70 %, kann im Einzelfall aber auch 40 % oder 90 % betragen. — printed p.22', verification_note='md-verified 2026-09-05 (§4.1.5.2, printed p.22) [VC]', verified_at=now() where id='5e0afa8e-6a29-4a8c-9d41-dc21fb85ed88' and verification_status not in ('verified_against_standard','corrected');
-- fkstrep
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 3: Eignungsklassen und Anwendungsbereiche von Bewässerungswasser [...] Fäkalstreptokokken KBE*/100 ml | 1 [...] nicht nachweisbar | 2 [...] ≤ 100 | 3 [...] 100 bis 400 | 4 [...] > 400 | *) KBE: Koloniebildende Einheiten. — printed p.12', verification_note='md-verified 2026-09-05 (§3.3 Tab. 3, printed p.12) [VC]', verified_at=now() where id='250ce0cc-f9e6-444b-b45f-454ffb5b7fb6' and verification_status not in ('verified_against_standard','corrected');
-- toc
