-- ---- M205-06 · Trinkwassergewinnung aus Oberflächengewässern ----
-- eps_potenzial
update public.fields set verification_status='verified_against_standard', verification_quote='Die Beschaffenheit des Zulaufes der nachgeschalteten Membrandesinfektionsanlage ist im Hinblick auf mögliche Störungen des Filtrationsprozesses insbesondere für die nachfolgend genannten Parameter zu charakterisieren: - Abfiltrierbare Stoffe, - Scalingverursacher, wie Eisen, Aluminium, Calcium, - Störstoffe wie Fette, Faserstoffe, extrazelluläre polymere Substanzen (EPS) bzw. das Bildungspotenzial für EPS. — printed p.23', verification_note='md-verified 2026-09-05 (§4.2.3.2, printed p.23) [VC] — the gering/mittel/hoch grading is EKOWAI’s; the source names only the parameter', verified_at=now() where id='063a2758-a156-4f72-b954-d5cd060d0bc9' and verification_status not in ('verified_against_standard','corrected');
-- vorsiebung_erforderlich
update public.fields set verification_status='verified_against_standard', verification_quote='Auf dieser Grundlage ist über die Notwendigkeit zusätzlicher Reinigungsstufen und die erforderlichen Reinigungsmaßnahmen zu entscheiden. In der Regel ist eine Vorsiebung bzw. -filtration erforderlich. — printed p.23', verification_note='md-verified 2026-09-05 (§4.2.3.2, printed p.23) [VC]', verified_at=now() where id='e977a1f9-91a1-4df2-b409-a14d3ef1dd78' and verification_status not in ('verified_against_standard','corrected');
-- porenweite
update public.fields set verification_status='verified_against_standard', verification_quote='Als Filtrationsmedium dienen Membranen mit definierter Porenweite. Zur Membrandesinfektion werden derzeit Mikro- oder Ultrafiltrationsmembranen mit mittleren Porenweiten von 0,01 µm bis 0,2 µm eingesetzt. — printed p.22', verification_note='md-verified 2026-09-05 (§4.2.2, printed p.22) [VC]', verified_at=now() where id='3259784e-6924-40ac-a11a-3eda23ba703d' and verification_status not in ('verified_against_standard','corrected');
-- membranverfahren
update public.fields set verification_status='verified_against_standard', verification_quote='Als Filtrationsmedium dienen Membranen mit definierter Porenweite. Zur Membrandesinfektion werden derzeit Mikro- oder Ultrafiltrationsmembranen mit mittleren Porenweiten von 0,01 µm bis 0,2 µm eingesetzt. | Tabelle 5: Zusammenstellung der Betriebsdaten von nachgeschalteten Membrandesinfektionsanlagen [...] Typ (Porengröße) & MF (0,1 µm) & UF (0,02 µm) & MF (0,2 µm) — printed p.22 / p.25', verification_note='md-verified 2026-09-05 (§4.2.2 + Tab. 5, printed p.22 / p.25) [VC]', verified_at=now() where id='b9abe918-ee95-4663-ad26-c886a6816120' and verification_status not in ('verified_against_standard','corrected');
-- membranbetrieb
update public.fields set verification_status='verified_against_standard', verification_quote='Es werden die Verfahrensweisen Dead-End-Filtration (statische Filtration) und Cross-Flow-Filtration (dynamische Filtration) unterschieden. | Abhängig von den eingesetzten Membran- bzw. Modulsystemen und Firmenkonzepten gibt es sowohl beim Betrieb als auch bei den Spül- und Reinigungsabläufen verschiedene Verfahrenskombinationen, wie: - Semi-Crossflow-Filtration, - konzentratseitige Luftblasenspülung, - zyklische Permeatrückspülungen mit Chemikalien. | Für die Planung einer Membrandesinfektion sind die folgenden Eckpunkte zu berücksichtigen: - Membranart, Modultyp, - Dead-End, Cross-Flow, Semi-Crossflow, - Zyklusschema, - Reinigungsschema. — printed p.22–23 / p.23 / p.24', verification_note='md-verified 2026-09-05 (§4.2.2 + §4.2.3.4, printed p.22–23 / p.24) [VC]', verified_at=now() where id='acfbc025-2576-47ea-ac19-ae3947b3ff1d' and verification_status not in ('verified_against_standard','corrected');
-- brutto_permeatfluss
update public.fields set verification_status='verified_against_standard', verification_quote='Die nachfolgend erläuterten Parameter gehen wesentlich in die Bemessung und Auslegung einer Membrandesinfektionsanlage, die Gestaltung der betrieblichen Abläufe sowie in die Beurteilung der Leistung ein: - Permeatfluss: Permeatvolumenstrom in $1 /\left(\mathrm{m}^{2} \cdot \mathrm{~h}\right)$, - Brutto-Permeatfluss: Permeatfluss während der Filtrationsphase in $1 /\left(\mathrm{m}^{2} \cdot \mathrm{~h}\right)$ — printed p.23', verification_note='md-verified 2026-09-05 (§4.2.3.1, printed p.23) [VC] — the md prints the unit as "1 /(m²·h)" (OCR of l/(m²·h))', verified_at=now() where id='ca4626ff-6d6d-41c2-aebd-c1885248f9b5' and verification_status not in ('verified_against_standard','corrected');
-- netto_permeatfluss
update public.fields set verification_status='verified_against_standard', verification_quote='Netto-Permeatfluss: im Dauerbetrieb je Betriebszyklus erzielbarer Permeatfluss (Permeatfluss bezogen auf die gesamte Zykluszeit abzüglich Spülverluste) in l/(m²·h) | Tabelle 5: Zusammenstellung der Betriebsdaten von nachgeschalteten Membrandesinfektionsanlagen [...] Mittlerer Netto-Permeatfluss & 50 l/(m²·h) & 12,5 l/(m²·h) (bei 736.221 m³/a) & 63 l/(m²·h) — printed p.23 / p.25', verification_note='md-verified 2026-09-05 (§4.2.3.1 + Tab. 5, printed p.23 / p.25) [VC]', verified_at=now() where id='fbc9b874-553b-4a09-972b-4cf444ee27ae' and verification_status not in ('verified_against_standard','corrected');
-- transmembrandruck
update public.fields set verification_status='verified_against_standard', verification_quote='Transmembrandruck: Druckunterschied zwischen Außen- und Innenseite der Membran in bar | Während des Betriebes lagert sich aus den zurückgehaltenen Partikeln eine reversible Deckschicht auf der Membran ab und der Transmembrandruck steigt an. Wird der maximal zulässige Betriebsdruck erreicht, muss die Deckschicht durch geeignete Spülverfahren entfernt werden. — printed p.23 / p.23', verification_note='md-verified 2026-09-05 (§4.2.3.1 + §4.2.2, printed p.23 / p.23) [VC]', verified_at=now() where id='3a16ecca-5797-4b30-abc8-4eceeb67461f' and verification_status not in ('verified_against_standard','corrected');
-- permeabilitaet
update public.fields set verification_status='verified_against_standard', verification_quote='Die nachfolgend erläuterten Parameter gehen wesentlich in die Bemessung und Auslegung einer Membrandesinfektionsanlage, die Gestaltung der betrieblichen Abläufe sowie in die Beurteilung der Leistung ein: [...] - Permeabilität: Verhältnis von Brutto-Permeatfluss und Transmembrandruck in $1 /\left(\mathrm{m}^{2} \cdot \mathrm{~h} \cdot \mathrm{bar}\right)$ — printed p.23', verification_note='md-verified 2026-09-05 (§4.2.3.1, printed p.23) [VC] — the md prints the unit as "1 /(m²·h·bar)" (OCR of l/(m²·h·bar))', verified_at=now() where id='9afc8be1-8034-4375-8389-7c2adff2af8e' and verification_status not in ('verified_against_standard','corrected');
-- arbeitsdruck
update public.fields set verification_status='verified_against_standard', verification_quote='Arbeitsdruck: für die Filtrationsleistung aktuell erforderlicher Druck (Transmembrandruck zzgl. Leitungsverluste) in bar | Tabelle 5: Zusammenstellung der Betriebsdaten von nachgeschalteten Membrandesinfektionsanlagen [...] Arbeitsdruck & 0,2 bar - 2 bar & 0,3 bar - 0,5 bar & 0,4 bar - 1,3 bar — printed p.23 / p.25', verification_note='md-verified 2026-09-05 (§4.2.3.1 + Tab. 5, printed p.23 / p.25) [VC]', verified_at=now() where id='4c169116-c0bb-4282-ad20-429ec0da0440' and verification_status not in ('verified_against_standard','corrected');
-- spez_energie_membran
update public.fields set verification_status='verified_against_standard', verification_quote='Bei einem spezifischen Energiebedarf von ca. 0,1 kWh/m³ bis 0,2 kWh/m³ Filtrat weist das Dead-end-Verfahren gegenüber dem Cross-flow-Verfahren Vorteile auf, wenn große Abwasservolumenströme mit geringer Feststoffbelastung (z. B. Kläranlagenabläufe) behandelt werden [27]. | Tabelle 5: Zusammenstellung der Betriebsdaten von nachgeschalteten Membrandesinfektionsanlagen [...] Energiebedarf & 0,4 kWh/m³ & 0,115 kWh/m³ (85.002 kWh/a) & 0,15 kWh/m³-0,2 kWh/m³ — printed p.22–23 / p.25', verification_note='md-verified 2026-09-05 (§4.2.2 + Tab. 5, printed p.22–23 / p.25) [VC]', verified_at=now() where id='38fd9b43-8bd9-4cd1-8fb6-33273d024cea' and verification_status not in ('verified_against_standard','corrected');
-- scaling_verursacher
update public.fields set verification_status='verified_against_standard', verification_quote='Die Beschaffenheit des Zulaufes der nachgeschalteten Membrandesinfektionsanlage ist im Hinblick auf mögliche Störungen des Filtrationsprozesses insbesondere für die nachfolgend genannten Parameter zu charakterisieren: - Abfiltrierbare Stoffe, - Scalingverursacher, wie Eisen, Aluminium, Calcium, - Störstoffe wie Fette, Faserstoffe, extrazelluläre polymere Substanzen (EPS) bzw. das Bildungspotenzial für EPS. — printed p.23', verification_note='md-verified 2026-09-05 (§4.2.3.2, printed p.23) [VC]', verified_at=now() where id='6c136f18-398d-40e6-81a9-ae39abbbf879' and verification_status not in ('verified_against_standard','corrected');
-- abwassertemperatur_bereich
update public.fields set verification_status='verified_against_standard', verification_quote='Die nachfolgend erläuterten Parameter gehen wesentlich in die Bemessung und Auslegung einer Membrandesinfektionsanlage, die Gestaltung der betrieblichen Abläufe sowie in die Beurteilung der Leistung ein: [...] - Abwassertemperatur-Bereich in ${ }^{\circ} \mathrm{C}$, - Arbeitsdruck: für die Filtrationsleistung aktuell erforderlicher Druck (Transmembrandruck zzgl. Leitungsverluste) in bar — printed p.23', verification_note='md-verified 2026-09-05 (§4.2.3.1, printed p.23) [VC]', verified_at=now() where id='940999fc-abf9-4b11-b94d-74b1d31d1d94' and verification_status not in ('verified_against_standard','corrected');

-- ---- M205-07 · Brauchwassernutzung und Arbeitsschutz (BioStoffV) ----
-- ozon_einsatzgas
update public.fields set verification_status='verified_against_standard', verification_quote='Ozon muss aufgrund seiner chemischen Instabilität vor Ort hergestellt werden. Dies erfolgt im Regelfall nach dem Prinzip der stillen elektrischen Entladung. Als Einsatzgase können technisch reiner Sauerstoff oder Luft verwendet werden. — printed p.27', verification_note='md-verified 2026-09-05 (§4.3.3.2, printed p.27) [VC]', verified_at=now() where id='c44e1224-6b29-4a19-a70d-182209f3e65e' and verification_status not in ('verified_against_standard','corrected');
-- ct_wert_zielorganismus
update public.fields set verification_status='verified_against_standard', verification_quote='Als besonders resistent gegen Ozon haben sich Protozoen-Dauerformen erwiesen. So übersteigt der $c t$-Wert für CryptosporidienOozysten den für Escherichia coli um ca. das Fünfhundertfache (bezüglich einer Reduktion der Keimzahl um 99 \%). Aufgrund der Reaktion von Ozon auch mit anderen, insbesondere organischen Wasserinhaltsstoffen, sowie der Milieuabhängigkeit ( pH -Wert, Temperatur) der Stabilität des Ozons hängen die erforderlichen Bedingungen von den Verhältnissen des Einzelfalles ab und müssen im Regelfall durch Vorversuche ermittelt werden. — printed p.26', verification_note='md-verified 2026-09-05 (§4.3.2, printed p.26) [VC] — the two-value enum is EKOWAI’s; the ct values themselves live in DVGW W 225 (NR)', verified_at=now() where id='c3121177-d9ca-49ee-aa1d-7ce27fbdf2ba' and verification_status not in ('verified_against_standard','corrected');
-- restozon_abluft
update public.fields set verification_status='verified_against_standard', verification_quote='Aufgrund seiner toxischen Eigenschaften muss das im Abgas der Anlagen enthaltene Restozon vor der Ableitung ins Freie abgesaugt und gezielt auf eine Konzentration von maximal 0,02 mg/m³ vermindert werden (Merkblatt DVGW W 625). Dies kann thermisch (Erhitzen auf 350 °C über mindestens 2 Sekunden) oder katalytisch (bei 60 °C bis 80 °C) erfolgen. — printed p.28', verification_note='md-verified 2026-09-05 (§4.3.3.4, printed p.28) [VC]', verified_at=now() where id='e8246a6f-4d46-4ce6-b7bd-a7c888bc1dc1' and verification_status not in ('verified_against_standard','corrected');
-- ozon_konz
update public.fields set verification_status='verified_against_standard', verification_quote='Gemäß der Ergebnisse der Pilotversuche können als Größenordnung für die wesentlichen Betriebsparameter genannt werden: - Erforderliche Ozonkonzentration: 2 mg bis 10 mg Ozon/l bzw. ca. $0,5 \mathrm{mg}$ bis 1 mg Ozon/mg DOC, - mindestens 5 bis 10 Minuten Aufenthaltszeit im Reaktionsbehälter. — printed p.28', verification_note='md-verified 2026-09-05 (§4.3.3.3, printed p.28) [VC] — printed as Größenordnung from pilot trials, not a limit', verified_at=now() where id='29cf60ea-ff1e-4dc2-bbed-54c0c81d43b8' and verification_status not in ('verified_against_standard','corrected');
-- ozon_pro_doc
update public.fields set verification_status='verified_against_standard', verification_quote='Erforderliche Ozonkonzentration: 2 mg bis 10 mg Ozon/l bzw. ca. $0,5 \mathrm{mg}$ bis 1 mg Ozon/mg DOC | Die Bromatbildung kann minimiert werden, wenn Ozon proportional zum DOC ( $<0,8 \mathrm{mg} / \mathrm{mg}$ ) dosiert wird. — printed p.28 / p.29', verification_note='md-verified 2026-09-05 (§4.3.3.3 + §4.3.6, printed p.28 / p.29) [VC]', verified_at=now() where id='53e602ba-307f-4a25-a408-778da59252b1' and verification_status not in ('verified_against_standard','corrected');
-- ozon_aufenthaltszeit
update public.fields set verification_status='verified_against_standard', verification_quote='mindestens 5 bis 10 Minuten Aufenthaltszeit im Reaktionsbehälter. | Eine Verlängerung der Aufenthaltszeit auf ca. 15 bis 20 Minuten kann sinnvoll sein, um sicherzustellen, dass kein gelöstes Ozon in den Ablauf gelangt. — printed p.28', verification_note='md-verified 2026-09-05 (§4.3.3.3, printed p.28) [VC]', verified_at=now() where id='072060c4-24d6-4605-bbfa-2166868ba145' and verification_status not in ('verified_against_standard','corrected');
-- ct_wert
update public.fields set verification_status='verified_against_standard', verification_quote='Wesentlich für eine ausreichende Desinfektionswirkung ist die Einhaltung einer wirksamen Kombination von Ozonkonzentration (c) und Einwirkzeit ( $t$ ) ( $c t$-Konzept). Das für eine definierte Reduktion der Keimzahl einzuhaltende Produkt beider Größen ergibt den $c t$-Wert in $\mathrm{mg} \cdot \mathrm{min} \cdot \mathrm{l}^{-1}$, der für verschiedene Mikroorganismen experimentell bestimmt wurde (Merkblatt DVGW W 225). — printed p.26', verification_note='md-verified 2026-09-05 (§4.3.2, printed p.26) [VC]', verified_at=now() where id='f67c700f-4b2e-47cb-8eab-4fe84b704fe3' and verification_status not in ('verified_against_standard','corrected');
-- temperatur_ozonentfernung
update public.fields set verification_status='verified_against_standard', verification_quote='Aufgrund seiner toxischen Eigenschaften muss das im Abgas der Anlagen enthaltene Restozon vor der Ableitung ins Freie abgesaugt und gezielt auf eine Konzentration von maximal 0,02 mg/m³ vermindert werden (Merkblatt DVGW W 625). Dies kann thermisch (Erhitzen auf 350 °C über mindestens 2 Sekunden) oder katalytisch (bei 60 °C bis 80 °C) erfolgen. — printed p.28', verification_note='md-verified 2026-09-05 (§4.3.3.4, printed p.28) [VC]', verified_at=now() where id='4e85f63e-ce65-46e4-bcb8-3bace9ae889e' and verification_status not in ('verified_against_standard','corrected');
-- spez_energie_ozon
update public.fields set verification_status='verified_against_standard', verification_quote='Der spezifische Energieverbrauch der Ozonerzeugung aus Reinsauerstoff beträgt etwa 10 kWh/kg Ozon. Bei Verwendung von Luft beträgt er ca. 60 % mehr. — printed p.27', verification_note='md-verified 2026-09-05 (§4.3.3.2, printed p.27) [VC]', verified_at=now() where id='cd656b06-988a-472d-abea-9f09f0a4ca68' and verification_status not in ('verified_against_standard','corrected');
-- spez_energie_anlage_ozon
update public.fields set verification_status='verified_against_standard', verification_quote='Insgesamt kann bei Einsatz von technisch reinem Sauerstoff und bei einem Einsatz von 10 mg Ozon/l Kläranlagenablauf von einem spezifischen Energieverbrauch von 0,1 kWh bis 0,15 kWh je Kubikmeter Abwasser ausgegangen werden. — printed p.28', verification_note='md-verified 2026-09-05 (§4.3.4, printed p.28) [VC]', verified_at=now() where id='8bcb0717-52f3-450d-ac1b-fcd49cb63886' and verification_status not in ('verified_against_standard','corrected');
-- kosten_ozon_cent_m3
update public.fields set verification_status='verified_against_standard', verification_quote='Diese lagen bei einer Ausbaugröße von 30.500 EW (max. 900 m³/h) bei 5,7 Cent/m³ (Anteil der Investition ca. 60 %); bei einer Ausbaugröße von 1,6 Mio EW (max. 200.000 m³/d) bei 1 Cent/m³ bis 2,2 Cent/m³ (je nach Verfahrensvariante; Anteil der Investition 20 % bis 30 %). Es ist zu berücksichtigen, dass diese Kostenschätzungen nicht auf die reine Desinfektionswirkung bezogen sind, sondern auch den Abbau von Spurenstoffen berücksichtigen. — printed p.28', verification_note='md-verified 2026-09-05 (§4.3.5, printed p.28) [VC]', verified_at=now() where id='6e27a361-15d7-425f-91d7-2a88ea38579c' and verification_status not in ('verified_against_standard','corrected');
-- ziel_brauchwasser_oder_vollentkeimung
update public.fields set verification_status='verified_against_standard', verification_quote='Die nachgeschaltete Membrandesinfektion wurde bisher nur bei wenigen Kläranlagen großtechnisch betrieben bzw. erprobt, um den gesamten Kläranlagenablauf aufgrund besonderer gewässergütewirtschaftlicher Anforderungen oder einen Teilstrom zur Brauchwasseraufbereitung zu desinfizieren [23;24;27]. — printed p.22', verification_note='md-verified 2026-09-05 (§4.2.1, printed p.22) [VC]', verified_at=now() where id='94b02e51-7c9b-4c7f-b06b-6d82f81b44a5' and verification_status not in ('verified_against_standard','corrected');
-- ozon_aus_o2_anteil
update public.fields set verification_status='verified_against_standard', verification_quote='Anlagen für Ozonleistungen über $1 \mathrm{~kg} / \mathrm{h}$ arbeiten bei einer Spannung von ca. 10 kV und einer Frequenz von ca. 600 Hz . Für 1 kg Ozon werden etwa 10 kg Sauerstoff benötigt (bei ca. $10 \%$ bis $13 \%$ Ozon im erzeugten Gasgemisch). Pro Kubikmeter Reinsauerstoff können so ca. 150 g bis 200 g Ozon erzeugt werden. — printed p.27', verification_note='md-verified 2026-09-05 (§4.3.3.2, printed p.27) [VC]', verified_at=now() where id='5fa126ac-8f82-481f-a450-937b727da00d' and verification_status not in ('verified_against_standard','corrected');
-- ozon_pro_o2
update public.fields set verification_status='verified_against_standard', verification_quote='Anlagen für Ozonleistungen über $1 \mathrm{~kg} / \mathrm{h}$ arbeiten bei einer Spannung von ca. 10 kV und einer Frequenz von ca. 600 Hz . Für 1 kg Ozon werden etwa 10 kg Sauerstoff benötigt (bei ca. $10 \%$ bis $13 \%$ Ozon im erzeugten Gasgemisch). Pro Kubikmeter Reinsauerstoff können so ca. 150 g bis 200 g Ozon erzeugt werden. — printed p.27', verification_note='md-verified 2026-09-05 (§4.3.3.2, printed p.27) [VC]', verified_at=now() where id='8042500e-b7ea-42d2-aec2-462fd4222a99' and verification_status not in ('verified_against_standard','corrected');
