-- bromat_bildung
update public.fields set verification_status='verified_against_standard', verification_quote='Die Ozonung von bromidhaltigem Abwasser kann zur Bildung von Bromat führen, dessen Einleitung in Gewässer aufgrund seiner toxikologischen Eigenschaften grundsätzlich unerwünscht ist. Für Oberflächengewässer bestehen keine spezifischen Qualitätsnormen. Die Bromatbildung kann minimiert werden, wenn Ozon proportional zum DOC ( $<0,8 \mathrm{mg} / \mathrm{mg}$ ) dosiert wird. — printed p.29', verification_note='md-verified 2026-09-05 (§4.3.6, printed p.29) [VC] — no bromate concentration limit printed; unit µg/l is EKOWAI’s', verified_at=now() where id='6a60a5bd-9ad1-40e0-b9c0-0a386165c33e' and verification_status not in ('verified_against_standard','corrected');
-- ndma_bildung
update public.fields set verification_status='verified_against_standard', verification_quote='Aus organischen Aminen können durch Ozonung Nitrosamine mit krebserregender Wirkung entstehen. [...] In einem Pilotvorhaben [31] wurde die Bildung von 5 ng bis 15 ng NDMA/l beobachtet, wovon ca. 50 % in der nachfolgenden biologisch aktiven Sandfiltration wieder eliminiert wurden. — printed p.29', verification_note='md-verified 2026-09-05 (§4.3.6, printed p.29) [VC]', verified_at=now() where id='7569d0e6-6ccf-4789-8a86-4f04912b11a2' and verification_status not in ('verified_against_standard','corrected');
-- verbrennung_typ
update public.fields set verification_status='verified_against_standard', verification_quote='Aufgrund seiner toxischen Eigenschaften muss das im Abgas der Anlagen enthaltene Restozon vor der Ableitung ins Freie abgesaugt und gezielt auf eine Konzentration von maximal 0,02 mg/m³ vermindert werden (Merkblatt DVGW W 625). Dies kann thermisch (Erhitzen auf 350 °C über mindestens 2 Sekunden) oder katalytisch (bei 60 °C bis 80 °C) erfolgen. — printed p.28', verification_note='md-verified 2026-09-05 (§4.3.3.4, printed p.28) [VC]', verified_at=now() where id='605bdea7-53bc-465f-9762-b7ad72284ce1' and verification_status not in ('verified_against_standard','corrected');
-- brauchwasser_standzeit_h
update public.fields set verification_status='verified_against_standard', verification_quote='Um die Bildung unerwünschter Gerüche, Beläge und Verschleimungen in Behältern und Rohrleitungen und ähnlich störende Effekte zu verhindern und zur Keimreduzierung kann eine Abwasserdesinfektion sinnvoll sein. Insbesondere bei längeren Standzeiten ist die Möglichkeit der Wiederverkeimung zu berücksichtigen. — printed p.13', verification_note='md-verified 2026-09-05 (§3.5, printed p.13) [VC] — no numeric hours printed; unit h is EKOWAI’s', verified_at=now() where id='d8106bac-47f8-40b8-beeb-97ff09fe5292' and verification_status not in ('verified_against_standard','corrected');
-- wiederverkeimungsbeurteilung
update public.fields set verification_status='verified_against_standard', verification_quote='Insbesondere bei längeren Standzeiten ist die Möglichkeit der Wiederverkeimung zu berücksichtigen. — printed p.13', verification_note='md-verified 2026-09-05 (§3.5, printed p.13) [VC]', verified_at=now() where id='f89a948a-507f-4028-9d7c-d1cd18e69e54' and verification_status not in ('verified_against_standard','corrected');
-- gefaehrdungsbeurteilung_biostoffv
update public.fields set verification_status='verified_against_standard', verification_quote='Der Arbeitgeber muss daher eine Gefährdungsbeurteilung durchführen, Verhaltensregeln und Schutzmaßnahmen in einer Betriebsanweisung vorgeben und die Arbeitnehmer entsprechend unterweisen. [...] Danach handelt es sich bei Arbeiten in abwassertechnischen Anlagen um nicht gezielte Tätigkeiten im Sinne der BioStoffV, die grundsätzlich der Schutzstufe 2 zugeordnet werden können. — printed p.13', verification_note='md-verified 2026-09-05 (§3.5, printed p.13) [VC]', verified_at=now() where id='05c324de-2ae7-464c-9251-40b72f74e170' and verification_status not in ('verified_against_standard','corrected');
-- betriebsanweisung_biostoffv
update public.fields set verification_status='verified_against_standard', verification_quote='Der Arbeitgeber muss daher eine Gefährdungsbeurteilung durchführen, Verhaltensregeln und Schutzmaßnahmen in einer Betriebsanweisung vorgeben und die Arbeitnehmer entsprechend unterweisen. [...] Danach handelt es sich bei Arbeiten in abwassertechnischen Anlagen um nicht gezielte Tätigkeiten im Sinne der BioStoffV, die grundsätzlich der Schutzstufe 2 zugeordnet werden können. — printed p.13', verification_note='md-verified 2026-09-05 (§3.5, printed p.13) [VC]', verified_at=now() where id='db5d2093-39bd-4d72-adf8-3443574f94a4' and verification_status not in ('verified_against_standard','corrected');

-- ---- M205-08 · Zulaufcharakterisierung Kläranlagenablauf ----
-- chlormittel_typ
update public.fields set verification_status='verified_against_standard', verification_quote='Eine Chlorung wird in der Regel unter Verwendung von Chlorgas ( $\mathrm{Cl}_{2}$ ), Hypochloritverbindungen, z. B. Natriumhypochlorit (NaOCl, Chlorbleichlauge) oder Chlordioxid $\left(\mathrm{ClO}_{2}\right)$ durchgeführt. — printed p.29', verification_note='md-verified 2026-09-05 (§4.4.2, printed p.29) [VC]', verified_at=now() where id='cd7e28f2-3765-43ec-837f-44955f9a6ca4' and verification_status not in ('verified_against_standard','corrected');
-- uvt
update public.fields set verification_status='verified_against_standard', verification_quote='Als Maß für die UV-C-Durchlässigkeit wird im Abwasserbereich in der Regel die UV-Transmission in %/cm, gemessen bei 1 cm Schichtdicke und 254 nm Wellenlänge, angegeben. | Bei Transmissionswerten unter 55 % bis 50 % sollte zunächst die Ursache erkundet und nach Möglichkeit beseitigt werden. — printed p.14 / p.15', verification_note='md-verified 2026-09-05 (§4.1.1 + §4.1.2.2, printed p.14 / p.15) [VC]', verified_at=now() where id='37416e41-1402-4099-b5c3-f13cb6e9ae1b' and verification_status not in ('verified_against_standard','corrected');
-- afs
update public.fields set verification_status='verified_against_standard', verification_quote='Das Abwasser sollte vor der Bestrahlung weitgehend biologisch gereinigt und luftblasenfrei sein sowie mit einer niedrigen Konzentration an abfiltrierbaren Stoffen der Bestrahlungsanlage zugeführt werden (< 20 mg/l, besser z. B. nach Filtration < 5 mg/l). Zumindest bei zu erwartenden abfiltrierbaren Stoffen in der Größenordnung von 10 mg/l bis 20 mg/l empfiehlt es sich zu überprüfen, ob für eine sichere Reduktion eine vorgeschaltete Abwasserfiltration erforderlich wird. — printed p.15', verification_note='md-verified 2026-09-05 (§4.1.2.2, printed p.15) [VC]', verified_at=now() where id='3db79a46-f1fb-4968-b211-a8fb5e3b0bf3' and verification_status not in ('verified_against_standard','corrected');
-- durchfluss_max
update public.fields set verification_status='verified_against_standard', verification_quote='Notwendige Parameter zur Auslegung einer UVBestrahlungsanlage sind die erforderliche UV-Dosis, der maximale Zufluss und die minimale Transmission. | Bei starken Durchfluss-Schwankungen, immer aber bei Durchflüssen über 1000 m³/h ist die Aufteilung des Gesamtdurchflusses auf parallel angeordnete Gerinne zweckmäßig. — printed p.16 / p.18', verification_note='md-verified 2026-09-05 (§4.1.2.3 + §4.1.3.2, printed p.16 / p.18) [VC]', verified_at=now() where id='c5f12c57-e9de-4ff2-8f86-04511009e35d' and verification_status not in ('verified_against_standard','corrected');
-- restchlor
update public.fields set verification_status='verified_against_standard', verification_quote='Zur Vermeidung von Beeinträchtigungen des Gewässers muss der Restchlorgehalt im Abwasser auf ein unschädliches Maß verringert werden. Die EGFischgewässerrichtlinie 2006/44/EG gibt z. B. einen Grenzwert für Restchlor von ≤ 0,005 mg/l im Gewässer vor. Daher ist eine zusätzliche Entchlorungsstufe erforderlich. — printed p.29', verification_note='md-verified 2026-09-05 (§4.4.2, printed p.29) [VC] — limit belongs to Richtlinie 2006/44/EG (external, quoted as example) — NR beyond the md', verified_at=now() where id='704dba77-0b4f-4f6a-9031-1da8e7cea1ae' and verification_status not in ('verified_against_standard','corrected');
-- ph_chlorung
update public.fields set verification_status='verified_against_standard', verification_quote='Je nach dem Gehalt an organischen Stoffen im Abwasser sind 1 mg bis 20 mg freies Chlor pro Liter, eine gründliche Durchmischung sowie eine Kontaktzeit von 15 bis 30 Minuten erforderlich. Eine geregelte Desinfektion ist nur dann gewährleistet, wenn ein pH-Bereich zwischen 6 und 8 eingehalten wird. — printed p.29', verification_note='md-verified 2026-09-05 (§4.4.2, printed p.29) [VC]', verified_at=now() where id='3d7e909b-e700-4150-b5a2-a3833dfdceb9' and verification_status not in ('verified_against_standard','corrected');
-- doc
update public.fields set verification_status='verified_against_standard', verification_quote='Die Ozondosierung kann durchflussabhängig und/oder in Abhängigkeit vom DOC-Gehalt des Kläranlagenablaufes gesteuert werden (sofern stärkere DOC-Schwankungen zu erwarten sind). | Die Bromatbildung kann minimiert werden, wenn Ozon proportional zum DOC (< 0,8 mg/mg) dosiert wird. — printed p.28 / p.29', verification_note='md-verified 2026-09-05 (§4.3.3.3 + §4.3.6, printed p.28 / p.29) [VC]', verified_at=now() where id='e19b4d2b-f2f1-4ae2-9b0f-71789359e548' and verification_status not in ('verified_against_standard','corrected');
-- bromid
update public.fields set verification_status='verified_against_standard', verification_quote='Die Ozonung von bromidhaltigem Abwasser kann zur Bildung von Bromat führen, dessen Einleitung in Gewässer aufgrund seiner toxikologischen Eigenschaften grundsätzlich unerwünscht ist. Für Oberflächengewässer bestehen keine spezifischen Qualitätsnormen. — printed p.29', verification_note='md-verified 2026-09-05 (§4.3.6, printed p.29) [VC] — no bromide limit printed', verified_at=now() where id='1c714405-d4c0-488b-b36a-88a3324267d8' and verification_status not in ('verified_against_standard','corrected');
-- clo2_dosis
update public.fields set verification_status='verified_against_standard', verification_quote='Bei Verwendung von gereinigtem Abwasser als Betriebswasser in Kläranlagen sind etwa 5 g bis 10 g Chlordioxid pro Kubikmeter Abwasser zur Reduktion der Fäkalindikatorbakterien um drei Zehnerpotenzen notwendig, bei sandfiltriertem Abwasser mit geringer Restverschmutzung nur 1 g/m³ bis 5 g/m³. Die erforderliche Einwirkzeit beträgt wenige Minuten. — printed p.29–30', verification_note='md-verified 2026-09-05 (§4.4.2, printed p.29–30) [VC]', verified_at=now() where id='ccea254e-10ad-42bf-b621-ba48a7a4bf3e' and verification_status not in ('verified_against_standard','corrected');
-- freies_chlor
update public.fields set verification_status='verified_against_standard', verification_quote='Je nach dem Gehalt an organischen Stoffen im Abwasser sind 1 mg bis 20 mg freies Chlor pro Liter, eine gründliche Durchmischung sowie eine Kontaktzeit von 15 bis 30 Minuten erforderlich. Eine geregelte Desinfektion ist nur dann gewährleistet, wenn ein pH-Bereich zwischen 6 und 8 eingehalten wird. — printed p.29', verification_note='md-verified 2026-09-05 (§4.4.2, printed p.29) [VC]', verified_at=now() where id='435565fd-5341-408e-8f3b-f87cf14e54c9' and verification_status not in ('verified_against_standard','corrected');
-- kontaktzeit_chlor
