-- restchlor_betrieb
update public.fields set verification_status='verified_against_standard', verification_quote='In dem aus dem Behandlungsbecken abfließenden Abwasser muss noch ein Überschuss von freiem Chlor in der Größenordnung von 0,2 mg/l nachzuweisen sein, um die Desinfektionswirkung sicherzustellen. Dieser Restchlorgehalt muss vor Einleitung in ein Gewässer mit Hilfe einer Entchlorungsstufe entfernt werden. — printed p.29', verification_note='md-verified 2026-09-05 (§4.4.2, printed p.29) [VC]', verified_at=now() where id='04078ca9-94da-4140-adf1-6c9ec8adb27b' and verification_status not in ('verified_against_standard','corrected');
-- entchlorungsstufe
