-- pes_dosis
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 7: Zusammenstellung verschiedener Untersuchungen zur Desinfektion von biologisch gereinigten Abwasser mit Peressigsäure (PES) | PES-Konzentration mg/l & Kontaktzeit min & Parameter & Reinigungsergebnis & Quelle | 15 & 36 & Gesamt- und Fäkalcoliforme & ~ 4 Log-Stufen & [35] | 5-7 & 60 & Gesamtcoliforme & <1000/100 ml & [36] | 5-10 & 35-50 & Escherichia coli & ~ 4 Log-Stufen & [39] | 8 & 30 & Gesamtcoliforme & ~ 4 Log-Stufen & [37] | 10 & 10 & Gesamt- und Fäkalcoliforme & ~ 3 Log-Stufen & [40] — printed p.31', verification_note='md-verified 2026-09-05 (§4.4.3 Tab. 7, printed p.31) [VC] — study compilation, not a limit', verified_at=now() where id='c575c6e2-2506-4816-bfa0-1c5ecd8d8398' and verification_status not in ('verified_against_standard','corrected');
-- kontaktzeit_pes
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 7: Zusammenstellung verschiedener Untersuchungen zur Desinfektion von biologisch gereinigten Abwasser mit Peressigsäure (PES) | PES-Konzentration mg/l & Kontaktzeit min & Parameter & Reinigungsergebnis & Quelle | 15 & 36 & Gesamt- und Fäkalcoliforme & ~ 4 Log-Stufen & [35] | 5-7 & 60 & Gesamtcoliforme & <1000/100 ml & [36] | 5-10 & 35-50 & Escherichia coli & ~ 4 Log-Stufen & [39] | 8 & 30 & Gesamtcoliforme & ~ 4 Log-Stufen & [37] | 10 & 10 & Gesamt- und Fäkalcoliforme & ~ 3 Log-Stufen & [40] — printed p.31', verification_note='md-verified 2026-09-05 (§4.4.3 Tab. 7, printed p.31) [VC] — study compilation, not a limit', verified_at=now() where id='22db2afb-a42a-4e89-98f1-c866a9450b48' and verification_status not in ('verified_against_standard','corrected');
-- h2o2_einsatz
update public.fields set verification_status='verified_against_standard', verification_quote='Wasserstoffperoxid ist ein starkes Oxidationsmittel, welches grundsätzlich auch für eine Desinfektion von biologisch gereinigtem Abwasser in Frage kommt. Im Vergleich zur Peressigsäure benötigt man für eine vergleichbare Desinfektionswirkung jedoch höhere Konzentrationen und längere Kontaktzeiten [34]. — printed p.30', verification_note='md-verified 2026-09-05 (§4.4.4, printed p.30) [VC]', verified_at=now() where id='a0558428-117a-4f03-ba68-7c705542066f' and verification_status not in ('verified_against_standard','corrected');
