update public.fields set verification_status='verified_against_standard', verification_quote='Wasserstoffperoxid ist ein starkes Oxidationsmittel, welches grundsätzlich auch für eine Desinfektion von biologisch gereinigtem Abwasser in Frage kommt. Im Vergleich zur Peressigsäure benötigt man für eine vergleichbare Desinfektionswirkung jedoch höhere Konzentrationen und längere Kontaktzeiten [34]. — printed p.30', verification_note='md-verified 2026-09-05 (§4.4.4, printed p.30) [VC] — no numeric dose printed', verified_at=now() where id='ebb12442-bc76-4ebe-a375-3dcec708e69a' and verification_status not in ('verified_against_standard','corrected');
