-- ---- M205-09 · Verfahrensauswahl Desinfektion ----
-- pruefintervall_mikrobio
update public.fields set verification_status='verified_against_standard', verification_quote='Der direkte Nachweis einer ausreichenden Desinfektionsleistung kann abschließend nur durch mikrobiologische Untersuchungen geführt werden. Wird eine regelmäßige Betriebsüberwachung durchgeführt, sind monatliche Nachweise in der Regel ausreichend. — printed p.19–20', verification_note='md-verified 2026-09-05 (§4.1.4.2, printed p.19–20) [VC]', verified_at=now() where id='a927bf68-5fd1-44f7-900e-ad4cc8f058ee' and verification_status not in ('verified_against_standard','corrected');
-- uv_sensor_anzahl_pro_bank
update public.fields set verification_status='verified_against_standard', verification_quote='Je Bestrahlungsbank ist mindestens ein UV-Sensor zur Messung der Bestrahlungsstärke mit unterer Alarmgrenze zur kontinuierlichen Überwachung des Betriebes anzuordnen. [...] Wenn hintereinander liegende Bestrahlungsräume durchflussabhängig zu- und abgeschaltet werden, sind mindestens zwei UV-Sensoren erforderlich, einer im ständig eingeschalteten Bereich und einer im am häufigsten abgeschalteten Bereich. — printed p.18–19', verification_note='md-verified 2026-09-05 (§4.1.3.3, printed p.18–19) [VC]', verified_at=now() where id='945c00aa-5030-4d0f-af67-411174cb14a9' and verification_status not in ('verified_against_standard','corrected');
-- kalibrierintervall_sensor
update public.fields set verification_status='verified_against_standard', verification_quote='Die Sensoren zur Messung der Bestrahlungsstärke sollten erfahrungsgemäß alle vier Wochen gereinigt werden. Durch Laborvergleichsmessungen kann die Funktion der Transmissionsmessung überprüft werden. Eine halbjährliche Kalibrierung sollte für die Messung der Bestrahlungsstärke und der Transmission vorgesehen werden. — printed p.19', verification_note='md-verified 2026-09-05 (§4.1.4.2, printed p.19) [VC]', verified_at=now() where id='607e90ab-331a-47ff-8c3c-63e238eec3a4' and verification_status not in ('verified_against_standard','corrected');
-- reinigungsintervall_sensor
update public.fields set verification_status='verified_against_standard', verification_quote='Die Sensoren zur Messung der Bestrahlungsstärke sollten erfahrungsgemäß alle vier Wochen gereinigt werden. Durch Laborvergleichsmessungen kann die Funktion der Transmissionsmessung überprüft werden. Eine halbjährliche Kalibrierung sollte für die Messung der Bestrahlungsstärke und der Transmission vorgesehen werden. — printed p.19', verification_note='md-verified 2026-09-05 (§4.1.4.2, printed p.19) [VC]', verified_at=now() where id='894bd621-937e-44c7-90f3-eaf0518d60b0' and verification_status not in ('verified_against_standard','corrected');
-- monatlicher_nachweis
update public.fields set verification_status='verified_against_standard', verification_quote='Der direkte Nachweis einer ausreichenden Desinfektionsleistung kann abschließend nur durch mikrobiologische Untersuchungen geführt werden. Wird eine regelmäßige Betriebsüberwachung durchgeführt, sind monatliche Nachweise in der Regel ausreichend. — printed p.19–20', verification_note='md-verified 2026-09-05 (§4.1.4.2, printed p.19–20) [VC]', verified_at=now() where id='5a4320ee-b765-4ed9-8a56-78b790207caa' and verification_status not in ('verified_against_standard','corrected');
-- verfahren
update public.fields set verification_status='verified_against_standard', verification_quote='Zur Desinfektion des Gesamtablaufes kommt derzeit im Wesentlichen die UV-Bestrahlung zum Einsatz. Die Membranfiltration ist bei einer Reihe von MBR-Anlagen in Betrieb. Die nachgeschaltete Membrandesinfektion ist bisher nur auf Einzelfälle beschränkt. Die Ozonung wurde in mehreren Pilotvorhaben untersucht. | Neben Ozon können grundsätzlich auch andere starke Oxidationsmittel zur Abwasserdesinfektion eingesetzt werden. Im Folgenden wird auf die Chlorung und die Behandlung mit Peroxidverbindungen eingegangen. — printed p.31 / p.29', verification_note='md-verified 2026-09-05 (§5 + §4.4.1, printed p.31 / p.29) [VC]', verified_at=now() where id='80d3e3e1-13df-4f52-9a53-5febe6a2ad77' and verification_status not in ('verified_against_standard','corrected');
-- chlorung_routine
update public.fields set verification_status='verified_against_standard', verification_quote='Daher kommt die Chlorung im deutschen Sprachraum als Routineverfahren für die Abwasserdesinfektion nicht zum Einsatz. Allenfalls wird bei Abwasser, das bereits mit einem anderen Verfahren (z. B. Membranfiltration) desinfiziert wurde, eine zusätzliche Depotchlorung durchgeführt, um im Zuge der weiteren Verwendung des desinfizierten Abwassers als Brauchwasser eine Wiederverkeimung zu verhindern. | In Deutschland besteht seit längerer Zeit Konsens, dass eine chemische Desinfektion des Gesamtablaufes von Kläranlagen mit Chlor wegen der Bildung unerwünschter Folgeprodukte als Dauerlösung abzulehnen ist. — printed p.29 / p.31', verification_note='md-verified 2026-09-05 (§4.4.2 + §5, printed p.29 / p.31) [VC]', verified_at=now() where id='ecc92e96-0eee-44a4-b030-0f20d7dc711b' and verification_status not in ('verified_against_standard','corrected');
-- vergleich_e_coli_erreichbar
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 8: Überblick über Desinfektionsverfahren | Einhaltbare Konzentration (E. coli/ 100 ml ) & + & < 10 (bei $400 \mathrm{~mJ} / \mathrm{s}- 700 \mathrm{~mJ} / \mathrm{s}$ ) & + & < 10 (Mikro-/Ultrafiltration) & + & < 100 (0,8 g Ozon/g DOC) — printed p.32', verification_note='md-verified 2026-09-05 (§5 Tab. 8, printed p.32) [VC] — Tab. 8 prints concentrations per 100 ml, the encoded unit „log“ is wrong (STAGED)', verified_at=now() where id='1d19721c-98bc-42a9-a67a-741e781d65ae' and verification_status not in ('verified_against_standard','corrected');
-- vergleich_vorbehandlungsbedarf
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 8: Überblick über Desinfektionsverfahren | Notwendigkeit der Vorbehandlung & (-) & gegebenenfalls Filtration erforderlich & (-) & gegebenenfalls Vorfiltration erforderlich & + & Filtration nicht erforderlich — printed p.32', verification_note='md-verified 2026-09-05 (§5 Tab. 8, printed p.32) [VC]', verified_at=now() where id='61468763-3e77-461e-afd5-99f14fdb8995' and verification_status not in ('verified_against_standard','corrected');
-- empfohlenes_verfahren
update public.fields set verification_status='verified_against_standard', verification_quote='Zu beachten ist auch, dass der UV-Bestrahlung, Membrandesinfektion und Ozonung unterschiedliche Wirkprinzipien zugrunde liegen und daher auch die Wirkspektren unterschiedlich sind. Die Membranfiltration entfernt alle Keime in Abhängigkeit von der Porengröße. Bei UV-Bestrahlung und Ozonung hängt die Elimination auch von der Resistenz der vorhandenen Mikroorganismen ab. Das geeignete Desinfektionsverfahren ist daher im Einzelfall zu ermitteln. — printed p.31', verification_note='md-verified 2026-09-05 (§5, printed p.31) [VC] — the enum value „chlorung / sonstige oxidative Verfahren“ is EKOWAI’s grouping of §4.4', verified_at=now() where id='1d3b6adb-cf6f-4931-a065-098740c95d3a' and verification_status not in ('verified_against_standard','corrected');

-- ---- M205-10 · UV-Bestrahlung — Bemessung und Auslegung ----
-- uv_dosis
update public.fields set verification_status='verified_against_standard', verification_quote='Die Anzahl der Treffer pro Zelle ist von der UV-Bestrahlung (UV-Dosis) in $\mathrm{J} / \mathrm{m}^{2}$ abhängig, die jede Zelle beim Durchgang durch den Bestrahlungsraum erhält (DIN 5031-1). | Danach beträgt die Mindestbestrahlung etwa 300 J/m² bis 450 J/m² zur sicheren Einhaltung der Grenz- und Leitwerte der EG-Badegewässer-Richtlinie für biologisch gereinigtes Abwasser [...] Eine Auswertung der Daten von verschiedenen, im Betrieb befindlichen UVAnlagen zeigt eine Schwankungsbreite für die eingestellte Mindestbestrahlung von 400 J/m² bis 600 J/m² und im Einzelfall bis zu 700 J/m² [16]. — printed p.14 / p.16', verification_note='md-verified 2026-09-05 (§4.1.1 + §4.1.2.3, printed p.14 / p.16) [VC]', verified_at=now() where id='d7a49a13-d556-46a9-993e-e5e79eb7db9e' and verification_status not in ('verified_against_standard','corrected');
-- uvc_anteil
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 4: Merkmale und Eigenschaften von Niederdruck- und Mitteldruck-UV-Strahlern (Quelle: Technische Mitteilung 01/08 der figawa) | UV-C-Leistung ( 254 nm ) \% bezogen auf die eingespeiste elektr. Leistung bei neuem Strahler & \% & ca. 20-35 & ca. 8-15 — printed p.17', verification_note='md-verified 2026-09-05 (§4.1.3.1 Tab. 4, printed p.17) [VC]', verified_at=now() where id='6645ae96-7607-4b55-8f6b-41ef6536f359' and verification_status not in ('verified_against_standard','corrected');
-- uv_dosis_zielband
update public.fields set verification_status='verified_against_standard', verification_quote='Danach beträgt die Mindestbestrahlung etwa 300 J/m² bis 450 J/m² zur sicheren Einhaltung der Grenz- und Leitwerte der EG-Badegewässer-Richtlinie für biologisch gereinigtes Abwasser bei einer Konzentration an abfiltrierbaren Stoffen von 5 mg/l bis 20 mg/l. | Entsprechend den Anforderungen kann die notwendige Mindestbestrahlung aber auch höher liegen. An der Isar wurde als Zielvorgabe die Unterschreitung der Leitwerte um eine Zehnerpotenz vorgegeben. Eine Auswertung der Daten von verschiedenen, im Betrieb befindlichen UVAnlagen zeigt eine Schwankungsbreite für die eingestellte Mindestbestrahlung von 400 J/m² bis 600 J/m² und im Einzelfall bis zu 700 J/m² [16]. — printed p.16', verification_note='md-verified 2026-09-05 (§4.1.2.3, printed p.16) [VC] — only two bands are printed; the third enum value „tab2_ausgezeichnet 400–700 J/m² (2006/7/EG)“ is not in the source (STAGED)', verified_at=now() where id='b809196f-5e89-43fc-a410-5aea8de4dcd7' and verification_status not in ('verified_against_standard','corrected');
-- uv_intensitaet
update public.fields set verification_status='verified_against_standard', verification_quote='Die UV-Bestrahlung, die eine Zelle im Mittel erhält, lässt sich rechnerisch als Produkt aus der mittleren Bestrahlungsstärke in $\mathrm{W} / \mathrm{m}^{2}$ und der mittleren Verweildauer in s abschätzen. Die Bestrahlungsstärke (Intensität) ist die pro Flächeneinheit ( $\mathrm{m}^{2}, \mathrm{~cm}^{2}$ ) auftreffende Strahlungsleistung ( $\mu \mathrm{W}, \mathrm{mW}, \mathrm{W}$ ). — printed p.14', verification_note='md-verified 2026-09-05 (§4.1.1, printed p.14) [VC]', verified_at=now() where id='d3b72649-3f1a-478f-80c8-aae1f5828001' and verification_status not in ('verified_against_standard','corrected');
-- verweildauer
update public.fields set verification_status='verified_against_standard', verification_quote='Die UV-Bestrahlung, die eine Zelle im Mittel erhält, lässt sich rechnerisch als Produkt aus der mittleren Bestrahlungsstärke in $\mathrm{W} / \mathrm{m}^{2}$ und der mittleren Verweildauer in s abschätzen. [...] Die Verweildauer ist die Zeit, die eine Zelle der UV-Strahlung ausgesetzt ist. — printed p.14', verification_note='md-verified 2026-09-05 (§4.1.1, printed p.14) [VC]', verified_at=now() where id='d2711cc5-a022-4d19-8221-e650651d72ca' and verification_status not in ('verified_against_standard','corrected');
-- e_coli_ablauf
