-- enterokokken_ablauf
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 2: Mikrobiologische Qualitätsanforderungen an Badegewässer nach der Richtlinie 2006/7/EG | Binnengewässer | Intestinale Enterokokken (cfu/100 ml) & 200 (95) & 400 (95) & 330 (90) & DIN EN ISO 7899-1 oder DIN EN ISO 7899-2 | Küstengewässer und Übergangsgewässer | Intestinale Enterokokken (cfu/100 ml) & 100 (95) & 200 (95) & 185 (90) — printed p.10', verification_note='md-verified 2026-09-05 (§3.2 Tab. 2, printed p.10) [VC]', verified_at=now() where id='86b9e22d-ec9d-405b-bb3d-bf3801e35b51' and verification_status not in ('verified_against_standard','corrected');
-- uvt_min
update public.fields set verification_status='verified_against_standard', verification_quote='Notwendige Parameter zur Auslegung einer UVBestrahlungsanlage sind die erforderliche UV-Dosis, der maximale Zufluss und die minimale Transmission. [...] Die Bemessungsvorgaben dieser UV-Anlagen für die Transmission liegen im Bereich > 60 % bis > 70 % (in der Regel > 65 %) und für die abfiltrierbaren Stoffe bei < 10 mg/l bzw. zum Teil auch < 5 mg/l. — printed p.16', verification_note='md-verified 2026-09-05 (§4.1.2.3, printed p.16) [VC]', verified_at=now() where id='7e2eb03a-bad1-4a96-bd0c-965e1147dede' and verification_status not in ('verified_against_standard','corrected');
-- strahlertyp
update public.fields set verification_status='verified_against_standard', verification_quote='UV-Strahlung wird technisch in der Regel durch Nieder-druck- oder Mitteldruck-Quecksilberdampf-Entladungslampen erzeugt. Mitteldruckstrahler weisen aufgrund ihres breitbandigen Spektrums eine deutlich geringere Energieeffizienz auf, können aber aufgrund der höheren Leistungsdichte kompakter ausgeführt werden. Niederdruckstrahler haben bezogen auf den elektrischen Energieverbrauch eine hohe UV-C-Ausbeute. — printed p.16–17', verification_note='md-verified 2026-09-05 (§4.1.3.1, printed p.16–17) [VC]', verified_at=now() where id='15725463-e1e5-4a6c-a51a-3ebb0541ce2e' and verification_status not in ('verified_against_standard','corrected');
