update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 1: Mikrobiologische Qualitätsanforderungen an Badegewässer nach der Richtlinie 76/160/EWG | Gesamtcoliforme Bakterien in 100 ml & 500 (80) & 10.000 (95) | Der Parameter „Gesamtcoliforme" ist weggefallen, da er auch in Gewässern ohne Fäkalieneintrag nachgewiesen wird. — printed p.10 / p.10–11', verification_note='md-verified 2026-09-05 (Tab. 1, printed p.10) [VC]', verified_at=now() where id='1efa74ad-7487-4218-8c5d-536a478219b3' and verification_status not in ('verified_against_standard','corrected');
-- faekalcoliforme_ablauf
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 1: Mikrobiologische Qualitätsanforderungen an Badegewässer nach der Richtlinie 76/160/EWG | Fäkalcoliforme Bakterien in 100 ml & 100 (80) & 2.000 (95) | Der Parameter „Escherichia coli“ entspricht den "Fäkalcoliformen Bakterien" und zeigt Keime an, die im Stuhl des Menschen vorkommen. — printed p.10 / p.10–11', verification_note='md-verified 2026-09-05 (Tab. 1, printed p.10) [VC]', verified_at=now() where id='b7376d4f-07b5-42d4-929e-24c2126091a2' and verification_status not in ('verified_against_standard','corrected');
