-- salmonellen
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 1: Mikrobiologische Qualitätsanforderungen an Badegewässer nach der Richtlinie 76/160/EWG | Salmonellen in 1000 ml*) & - & 0 (95) | *) Untersuchung auf Anforderung. | Salmonellen und potenziell infektiöse Stadien von Mensch- und Haustierparasiten dürfen nicht nachweisbar sein. — printed p.10 / p.11', verification_note='md-verified 2026-09-05 (Tab. 1 + §3.3, printed p.10 / p.11) [VC]', verified_at=now() where id='c84ff378-5b14-46a3-a72e-b5d7c62c05b2' and verification_status not in ('verified_against_standard','corrected');
-- darmviren
