-- log_reduktion
update public.fields set verification_status='verified_against_standard', verification_quote='Für die uneingeschränkte Nutzung wird eine Keimreduzierung um 6 bis 7 Log-Stufen empfohlen (bezogen auf eine Rohabwasserbelastung von 10⁷ Escherichia coli in 100 ml), für die eingeschränkte Nutzung um 4 LogStufen (bei arbeitsintensiver Bewirtschaftung) bzw. um 3 Log-Stufen (bei hoch mechanisierter Bewirtschaftung). | Die Reduktionsrate wird in der Regel in Log-Stufen oder Zehnerpotenzen angegeben und ist für die Bewertung der Leistungsfähigkeit eines Desinfektionsverfahrens wichtig. — printed p.11 / p.8', verification_note='md-verified 2026-09-05 (§3.3 + §2.1 Anmerkung, printed p.11 / p.8) [VC]', verified_at=now() where id='ae3b39d5-e5f5-4894-99ff-53eab0f3b799' and verification_status not in ('verified_against_standard','corrected');

-- ---- M205-11 · UV-Bestrahlung — Bau und Anlagentechnik ----
-- kapitalkostenanteil
update public.fields set verification_status='verified_against_standard', verification_quote='Der Kapitalkostenanteil betrug dabei 63 % bis 86 %. Legt man einen ganzjährigen Betrieb zugrunde läge die Spannbreite der spezifischen Kosten bei rund 2 Cent/m³ bis 6 Cent/m³. Der Kapitalkostenanteil würde sich dabei aufgrund der größeren desinfizierten Abwassermenge auf 47 % bis 76 % reduzieren. — printed p.22', verification_note='md-verified 2026-09-05 (§4.1.5.3, printed p.22) [VC]', verified_at=now() where id='ae7cfb5d-b197-4285-a65f-dfd646a23c08' and verification_status not in ('verified_against_standard','corrected');
-- gerinne_abdeckung_lichtdicht
update public.fields set verification_status='verified_against_standard', verification_quote='Die offenen Gerinne sollten vollständig abgedeckt werden, um sie vor Lichteinfall zu schützen. Es kann sonst zu erhöhtem Algenwachstum im Gerinne kommen, das sich negativ auf die Leistungsfähigkeit der Anlage auswirkt. Eine lichtdichte Abdeckung der Gerinne über den Strahlern ist aus Gründen des Arbeitsschutzes erforderlich. — printed p.18', verification_note='md-verified 2026-09-05 (§4.1.3.2, printed p.18) [VC]', verified_at=now() where id='1da69888-38fd-4a11-900d-d1539b72cbc0' and verification_status not in ('verified_against_standard','corrected');
