update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 4: Merkmale und Eigenschaften von Niederdruck- und Mitteldruck-UV-Strahlern | Merkmal & Einheit & Niederdruckstrahler & Mitteldruckstrahler | Typische Leistungsdichte bezogen auf die Lichtbogenlänge & $\mathrm{W} / \mathrm{cm}$ & 1-4 & 100-200 — printed p.17', verification_note='md-verified 2026-09-05 (§4.1.3.1 Tab. 4, printed p.17) [VC]', verified_at=now() where id='2c9a9174-43f4-431c-a1e6-ae955c5ef9c5' and verification_status not in ('verified_against_standard','corrected');
