update public.fields set verification_status='verified_against_standard', verification_quote='UV-C & UV-Strahlung im Wellenbereich 100 nm bis 280 nm | Tabelle 4: Merkmale und Eigenschaften von Niederdruck- und Mitteldruck-UV-Strahlern [...] Wellenlänge im UV-C-Bereich & nm & 254 nm & 240 nm-280 nm — printed p.8 / p.17', verification_note='md-verified 2026-09-05 (§2.2 + Tab. 4, printed p.8 / p.17) [VC]', verified_at=now() where id='eebffcb3-cad5-46b0-a8d6-bcfb5cd32b07' and verification_status not in ('verified_against_standard','corrected');
-- ip_schutzart
update public.fields set verification_status='verified_against_standard', verification_quote='Alle elektrischen Einrichtungen und Verbindungen müssen gut zugänglich sein und den Einsatzbedingungen in nasser und feuchter Umgebung entsprechen. Sie sind in IP 54-67 auszuführen. Schaltanlagen sind ebenfalls vorzugsweise in IP 67 auszuführen oder spritzwassergeschützt aufzustellen. — printed p.18', verification_note='md-verified 2026-09-05 (§4.1.3.2, printed p.18) [VC]', verified_at=now() where id='e4f77e48-3818-4dca-b4e2-bcd828d03363' and verification_status not in ('verified_against_standard','corrected');
-- abschreibungsdauer_baulich
update public.fields set verification_status='verified_against_standard', verification_quote='Zur Abschätzung der spezifischen Kosten wurde eine Kostenvergleichsrechnung gemäß den KVR-Leitlinien [22] durchgeführt und eine Abschreibungsdauer von 25 Jahren für den bautechnischen Teil und 12,5 Jahren für den elektro- und maschinentechnischen Teil angesetzt. — printed p.22', verification_note='md-verified 2026-09-05 (§4.1.5.3, printed p.22) [VC]', verified_at=now() where id='5016428c-5ffe-4a94-b3e6-cc6b91793f07' and verification_status not in ('verified_against_standard','corrected');
-- abschreibungsdauer_emt
update public.fields set verification_status='verified_against_standard', verification_quote='Zur Abschätzung der spezifischen Kosten wurde eine Kostenvergleichsrechnung gemäß den KVR-Leitlinien [22] durchgeführt und eine Abschreibungsdauer von 25 Jahren für den bautechnischen Teil und 12,5 Jahren für den elektro- und maschinentechnischen Teil angesetzt. — printed p.22', verification_note='md-verified 2026-09-05 (§4.1.5.3, printed p.22) [VC]', verified_at=now() where id='78f6eff3-523c-415c-aa35-cb0a4eeca4e6' and verification_status not in ('verified_against_standard','corrected');
-- nicht_bestrahltes_volumen
update public.fields set verification_status='verified_against_standard', verification_quote='Schon geringe Kurzschlussströmungen begrenzen die erreichbare Reduktionsleistung. Ein Prozent nicht bestrahltes Volumen reicht aus, um die maximale Reduktion auf zwei Log-Stufen zu begrenzen [7]. — printed p.14', verification_note='md-verified 2026-09-05 (§4.1.1, printed p.14) [VC]', verified_at=now() where id='8b1a3821-ded7-41e9-bd6a-48493d2eee06' and verification_status not in ('verified_against_standard','corrected');
-- mehrstrassige_anlage
update public.fields set verification_status='verified_against_standard', verification_quote='Bei starken Durchfluss-Schwankungen, immer aber bei Durchflüssen über 1000 m³/h ist die Aufteilung des Gesamtdurchflusses auf parallel angeordnete Gerinne zweckmäßig. Bei mehrstraßigen Anlagen ist durch steuerungstechnische und konstruktive Maßnahmen eine möglichst gleichmäßige Beschickung der Gerinne sicherzustellen. — printed p.18', verification_note='md-verified 2026-09-05 (§4.1.3.2, printed p.18) [VC]', verified_at=now() where id='c5940571-a635-40d4-87a9-2af14b1bd49f' and verification_status not in ('verified_against_standard','corrected');

-- ---- M205-12 · UV-Bestrahlung — Betrieb, Reinigung, Strahleraustausch, Arbeitsschutz ----
-- strahler_nutzungsdauer
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 4: Merkmale und Eigenschaften von Niederdruck- und Mitteldruck-UV-Strahlern [...] Mittlere Nutzungsdauer & h & 8.000-16.000 & 4.000-12.000 | Die garantierten Lebensdauern von UV-Strahlern liegen im Bereich von 8.000 bis 12.000 Betriebsstunden. | Sie sollten daher nach der vom Hersteller empfohlenen Nutzungsdauer ausgetauscht werden. — printed p.17 / p.22 / p.20', verification_note='md-verified 2026-09-05 (Tab. 4 + §4.1.5.2 + §4.1.4.4, printed p.17 / p.22 / p.20) [VC]', verified_at=now() where id='c992b863-e771-4498-b08a-83ea071c3827' and verification_status not in ('verified_against_standard','corrected');
-- strahler_auslastung_pct
update public.fields set verification_status='verified_against_standard', verification_quote='Die Strahlerauslastung (Laufzeit einzelner Banks im Verhältnis zur Gesamtbetriebszeit der Abwasserdesinfektion) der untersuchten Anlagen liegt in der Regel bei rund 50 % bis 70 %, kann im Einzelfall aber auch 40 % oder 90 % betragen. — printed p.22', verification_note='md-verified 2026-09-05 (§4.1.5.2, printed p.22) [VC]', verified_at=now() where id='c99c4a5c-41f2-41b3-a944-72f62a8c0eb8' and verification_status not in ('verified_against_standard','corrected');
-- hg_strahler_sonderentsorgung
update public.fields set verification_status='verified_against_standard', verification_quote='Mit zunehmendem Alter der UV-Strahler nimmt die UVBestrahlungsstärke ab. Sie sollten daher nach der vom Hersteller empfohlenen Nutzungsdauer ausgetauscht werden. [...] Die ausrangierten Strahler müssen wegen des Quecksilbergehaltes gesondert entsorgt werden. — printed p.20', verification_note='md-verified 2026-09-05 (§4.1.4.4, printed p.20) [VC]', verified_at=now() where id='df5909fc-4e94-4f90-bb77-0f5b00dd4aad' and verification_status not in ('verified_against_standard','corrected');

-- ---- M205-13 · UV-Bestrahlung — Kosten ----
-- spez_strom_uv
update public.fields set verification_status='verified_against_standard', verification_quote='Bei den ausgewerteten Desinfektionsanlagen bewegt sich der spezifische Stromverbrauch im Bereich von 30 Wh bis 60 Wh pro Kubikmeter behandelten Abwassers. — printed p.22', verification_note='md-verified 2026-09-05 (§4.1.5.2, printed p.22) [VC]', verified_at=now() where id='d0510688-edfa-47c9-be0a-24ac7267ff7f' and verification_status not in ('verified_against_standard','corrected');
-- invest_kosten_uv
update public.fields set verification_status='verified_against_standard', verification_quote='Die spezifischen Investitionskosten für UV-Anlagen gestalten sich tendenziell umso niedriger, je höher die Ausbaugröße ist (Bild 7), hängen jedoch im Einzelfall stark von den örtlichen Randbedingungen ab [...]. Die ermittelten Werte lagen zwischen 7 €/EW und 52 €/EW. Erhebliche zusätzliche Investitionskosten entstehen, wenn eine vorgeschaltete Filtration notwendig ist. — printed p.21', verification_note='md-verified 2026-09-05 (§4.1.5.1, printed p.21) [VC]', verified_at=now() where id='04ac331b-3829-4ee8-8577-34df619cd207' and verification_status not in ('verified_against_standard','corrected');
-- kosten_uv_cent_m3
update public.fields set verification_status='verified_against_standard', verification_quote='Die spezifischen Kosten (jährliche Kapital- und Betriebskosten pro Kubikmeter desinfizierten Abwassers) bewegen sich bei den ausgewerteten Anlagen im Bereich von ca. 3 Cent/m³ bis 10 Cent/m³ für einen in etwa halbjährigen Betrieb. [...] Legt man einen ganzjährigen Betrieb zugrunde läge die Spannbreite der spezifischen Kosten bei rund 2 Cent/m³ bis 6 Cent/m³. — printed p.22', verification_note='md-verified 2026-09-05 (§4.1.5.3, printed p.22) [VC]', verified_at=now() where id='b18ffb5a-5621-4e28-98c9-d746917de8c3' and verification_status not in ('verified_against_standard','corrected');

-- ---- M205-14 · Membranverfahren — Bemessung und Auslegung ----
-- eps_potenzial
update public.fields set verification_status='verified_against_standard', verification_quote='Die Beschaffenheit des Zulaufes der nachgeschalteten Membrandesinfektionsanlage ist im Hinblick auf mögliche Störungen des Filtrationsprozesses insbesondere für die nachfolgend genannten Parameter zu charakterisieren: - Abfiltrierbare Stoffe, - Scalingverursacher, wie Eisen, Aluminium, Calcium, - Störstoffe wie Fette, Faserstoffe, extrazelluläre polymere Substanzen (EPS) bzw. das Bildungspotenzial für EPS. — printed p.23', verification_note='md-verified 2026-09-05 (§4.2.3.2, printed p.23) [VC] — the gering/mittel/hoch grading is EKOWAI’s; the source names only the parameter', verified_at=now() where id='43778064-da08-4493-be5d-7bc12abd93b0' and verification_status not in ('verified_against_standard','corrected');
-- vorsiebung_erforderlich
update public.fields set verification_status='verified_against_standard', verification_quote='Auf dieser Grundlage ist über die Notwendigkeit zusätzlicher Reinigungsstufen und die erforderlichen Reinigungsmaßnahmen zu entscheiden. In der Regel ist eine Vorsiebung bzw. -filtration erforderlich. — printed p.23', verification_note='md-verified 2026-09-05 (§4.2.3.2, printed p.23) [VC]', verified_at=now() where id='375b6218-9048-4022-9a2e-9373c6a73466' and verification_status not in ('verified_against_standard','corrected');
-- porenweite
update public.fields set verification_status='verified_against_standard', verification_quote='Als Filtrationsmedium dienen Membranen mit definierter Porenweite. Zur Membrandesinfektion werden derzeit Mikro- oder Ultrafiltrationsmembranen mit mittleren Porenweiten von 0,01 µm bis 0,2 µm eingesetzt. — printed p.22', verification_note='md-verified 2026-09-05 (§4.2.2, printed p.22) [VC]', verified_at=now() where id='3d2f06ce-a7d3-4670-85b5-05be070e23c3' and verification_status not in ('verified_against_standard','corrected');
-- membranverfahren
update public.fields set verification_status='verified_against_standard', verification_quote='Als Filtrationsmedium dienen Membranen mit definierter Porenweite. Zur Membrandesinfektion werden derzeit Mikro- oder Ultrafiltrationsmembranen mit mittleren Porenweiten von 0,01 µm bis 0,2 µm eingesetzt. | Tabelle 5: Zusammenstellung der Betriebsdaten von nachgeschalteten Membrandesinfektionsanlagen [...] Typ (Porengröße) & MF (0,1 µm) & UF (0,02 µm) & MF (0,2 µm) — printed p.22 / p.25', verification_note='md-verified 2026-09-05 (§4.2.2 + Tab. 5, printed p.22 / p.25) [VC]', verified_at=now() where id='667b06ef-a3b0-4da8-99d0-8ec2b759a33a' and verification_status not in ('verified_against_standard','corrected');
-- membranbetrieb
update public.fields set verification_status='verified_against_standard', verification_quote='Es werden die Verfahrensweisen Dead-End-Filtration (statische Filtration) und Cross-Flow-Filtration (dynamische Filtration) unterschieden. | Abhängig von den eingesetzten Membran- bzw. Modulsystemen und Firmenkonzepten gibt es sowohl beim Betrieb als auch bei den Spül- und Reinigungsabläufen verschiedene Verfahrenskombinationen, wie: - Semi-Crossflow-Filtration, - konzentratseitige Luftblasenspülung, - zyklische Permeatrückspülungen mit Chemikalien. | Für die Planung einer Membrandesinfektion sind die folgenden Eckpunkte zu berücksichtigen: - Membranart, Modultyp, - Dead-End, Cross-Flow, Semi-Crossflow, - Zyklusschema, - Reinigungsschema. — printed p.22–23 / p.23 / p.24', verification_note='md-verified 2026-09-05 (§4.2.2 + §4.2.3.4, printed p.22–23 / p.24) [VC]', verified_at=now() where id='7f6f2f6a-9d44-40ac-bf8b-5ba08c260ebe' and verification_status not in ('verified_against_standard','corrected');
-- brutto_permeatfluss
update public.fields set verification_status='verified_against_standard', verification_quote='Die nachfolgend erläuterten Parameter gehen wesentlich in die Bemessung und Auslegung einer Membrandesinfektionsanlage, die Gestaltung der betrieblichen Abläufe sowie in die Beurteilung der Leistung ein: - Permeatfluss: Permeatvolumenstrom in $1 /\left(\mathrm{m}^{2} \cdot \mathrm{~h}\right)$, - Brutto-Permeatfluss: Permeatfluss während der Filtrationsphase in $1 /\left(\mathrm{m}^{2} \cdot \mathrm{~h}\right)$ — printed p.23', verification_note='md-verified 2026-09-05 (§4.2.3.1, printed p.23) [VC] — the md prints the unit as "1 /(m²·h)" (OCR of l/(m²·h))', verified_at=now() where id='4f282b6f-2b1d-4ce8-a2a0-5d9f7913d8d6' and verification_status not in ('verified_against_standard','corrected');
-- netto_permeatfluss
update public.fields set verification_status='verified_against_standard', verification_quote='Netto-Permeatfluss: im Dauerbetrieb je Betriebszyklus erzielbarer Permeatfluss (Permeatfluss bezogen auf die gesamte Zykluszeit abzüglich Spülverluste) in l/(m²·h) | Tabelle 5: Zusammenstellung der Betriebsdaten von nachgeschalteten Membrandesinfektionsanlagen [...] Mittlerer Netto-Permeatfluss & 50 l/(m²·h) & 12,5 l/(m²·h) (bei 736.221 m³/a) & 63 l/(m²·h) — printed p.23 / p.25', verification_note='md-verified 2026-09-05 (§4.2.3.1 + Tab. 5, printed p.23 / p.25) [VC]', verified_at=now() where id='0cb345d3-27e1-43bb-bc7e-510d117734b6' and verification_status not in ('verified_against_standard','corrected');
-- transmembrandruck
update public.fields set verification_status='verified_against_standard', verification_quote='Transmembrandruck: Druckunterschied zwischen Außen- und Innenseite der Membran in bar | Während des Betriebes lagert sich aus den zurückgehaltenen Partikeln eine reversible Deckschicht auf der Membran ab und der Transmembrandruck steigt an. Wird der maximal zulässige Betriebsdruck erreicht, muss die Deckschicht durch geeignete Spülverfahren entfernt werden. — printed p.23 / p.23', verification_note='md-verified 2026-09-05 (§4.2.3.1 + §4.2.2, printed p.23 / p.23) [VC]', verified_at=now() where id='3bbf0eb6-69ce-4a05-9f05-639187622424' and verification_status not in ('verified_against_standard','corrected');
-- permeabilitaet
update public.fields set verification_status='verified_against_standard', verification_quote='Die nachfolgend erläuterten Parameter gehen wesentlich in die Bemessung und Auslegung einer Membrandesinfektionsanlage, die Gestaltung der betrieblichen Abläufe sowie in die Beurteilung der Leistung ein: [...] - Permeabilität: Verhältnis von Brutto-Permeatfluss und Transmembrandruck in $1 /\left(\mathrm{m}^{2} \cdot \mathrm{~h} \cdot \mathrm{bar}\right)$ — printed p.23', verification_note='md-verified 2026-09-05 (§4.2.3.1, printed p.23) [VC] — the md prints the unit as "1 /(m²·h·bar)" (OCR of l/(m²·h·bar))', verified_at=now() where id='2b395426-5bff-425b-be59-1b88a9cd49d3' and verification_status not in ('verified_against_standard','corrected');
-- arbeitsdruck
update public.fields set verification_status='verified_against_standard', verification_quote='Arbeitsdruck: für die Filtrationsleistung aktuell erforderlicher Druck (Transmembrandruck zzgl. Leitungsverluste) in bar | Tabelle 5: Zusammenstellung der Betriebsdaten von nachgeschalteten Membrandesinfektionsanlagen [...] Arbeitsdruck & 0,2 bar - 2 bar & 0,3 bar - 0,5 bar & 0,4 bar - 1,3 bar — printed p.23 / p.25', verification_note='md-verified 2026-09-05 (§4.2.3.1 + Tab. 5, printed p.23 / p.25) [VC]', verified_at=now() where id='648ce278-13bf-4ee9-aa77-abf93f23af07' and verification_status not in ('verified_against_standard','corrected');
-- scaling_verursacher
update public.fields set verification_status='verified_against_standard', verification_quote='Die Beschaffenheit des Zulaufes der nachgeschalteten Membrandesinfektionsanlage ist im Hinblick auf mögliche Störungen des Filtrationsprozesses insbesondere für die nachfolgend genannten Parameter zu charakterisieren: - Abfiltrierbare Stoffe, - Scalingverursacher, wie Eisen, Aluminium, Calcium, - Störstoffe wie Fette, Faserstoffe, extrazelluläre polymere Substanzen (EPS) bzw. das Bildungspotenzial für EPS. — printed p.23', verification_note='md-verified 2026-09-05 (§4.2.3.2, printed p.23) [VC]', verified_at=now() where id='d974d290-50f4-425f-8674-e97cc6d2fda2' and verification_status not in ('verified_against_standard','corrected');
