-- ---- M205-15 · Membranverfahren — Planung, Betrieb, Kosten ----
-- spez_energie_membran
update public.fields set verification_status='verified_against_standard', verification_quote='Bei einem spezifischen Energiebedarf von ca. 0,1 kWh/m³ bis 0,2 kWh/m³ Filtrat weist das Dead-end-Verfahren gegenüber dem Cross-flow-Verfahren Vorteile auf, wenn große Abwasservolumenströme mit geringer Feststoffbelastung (z. B. Kläranlagenabläufe) behandelt werden [27]. | Tabelle 5: Zusammenstellung der Betriebsdaten von nachgeschalteten Membrandesinfektionsanlagen [...] Energiebedarf & 0,4 kWh/m³ & 0,115 kWh/m³ (85.002 kWh/a) & 0,15 kWh/m³-0,2 kWh/m³ — printed p.22–23 / p.25', verification_note='md-verified 2026-09-05 (§4.2.2 + Tab. 5, printed p.22–23 / p.25) [VC]', verified_at=now() where id='b8e3428f-06c2-490b-a7d6-30ea6740e06f' and verification_status not in ('verified_against_standard','corrected');

-- ---- M205-17 · Ozonung — Bemessung und Anlagentechnik ----
-- ozon_einsatzgas
update public.fields set verification_status='verified_against_standard', verification_quote='Ozon muss aufgrund seiner chemischen Instabilität vor Ort hergestellt werden. Dies erfolgt im Regelfall nach dem Prinzip der stillen elektrischen Entladung. Als Einsatzgase können technisch reiner Sauerstoff oder Luft verwendet werden. — printed p.27', verification_note='md-verified 2026-09-05 (§4.3.3.2, printed p.27) [VC]', verified_at=now() where id='a4b2a95a-5000-4e6d-90cb-a95c8a30d37d' and verification_status not in ('verified_against_standard','corrected');
-- ct_wert_zielorganismus
update public.fields set verification_status='verified_against_standard', verification_quote='Als besonders resistent gegen Ozon haben sich Protozoen-Dauerformen erwiesen. So übersteigt der $c t$-Wert für CryptosporidienOozysten den für Escherichia coli um ca. das Fünfhundertfache (bezüglich einer Reduktion der Keimzahl um 99 \%). Aufgrund der Reaktion von Ozon auch mit anderen, insbesondere organischen Wasserinhaltsstoffen, sowie der Milieuabhängigkeit ( pH -Wert, Temperatur) der Stabilität des Ozons hängen die erforderlichen Bedingungen von den Verhältnissen des Einzelfalles ab und müssen im Regelfall durch Vorversuche ermittelt werden. — printed p.26', verification_note='md-verified 2026-09-05 (§4.3.2, printed p.26) [VC] — the two-value enum is EKOWAI’s; the ct values themselves live in DVGW W 225 (NR)', verified_at=now() where id='30bbb117-eb3c-47f1-b0d0-b6aa37af4a83' and verification_status not in ('verified_against_standard','corrected');
-- ozon_konz
update public.fields set verification_status='verified_against_standard', verification_quote='Gemäß der Ergebnisse der Pilotversuche können als Größenordnung für die wesentlichen Betriebsparameter genannt werden: - Erforderliche Ozonkonzentration: 2 mg bis 10 mg Ozon/l bzw. ca. $0,5 \mathrm{mg}$ bis 1 mg Ozon/mg DOC, - mindestens 5 bis 10 Minuten Aufenthaltszeit im Reaktionsbehälter. — printed p.28', verification_note='md-verified 2026-09-05 (§4.3.3.3, printed p.28) [VC] — printed as Größenordnung from pilot trials, not a limit', verified_at=now() where id='69f5782c-9d55-4fef-86aa-20450601f316' and verification_status not in ('verified_against_standard','corrected');
-- ozon_pro_doc
update public.fields set verification_status='verified_against_standard', verification_quote='Erforderliche Ozonkonzentration: 2 mg bis 10 mg Ozon/l bzw. ca. $0,5 \mathrm{mg}$ bis 1 mg Ozon/mg DOC | Die Bromatbildung kann minimiert werden, wenn Ozon proportional zum DOC ( $<0,8 \mathrm{mg} / \mathrm{mg}$ ) dosiert wird. — printed p.28 / p.29', verification_note='md-verified 2026-09-05 (§4.3.3.3 + §4.3.6, printed p.28 / p.29) [VC]', verified_at=now() where id='3d410f2e-07a0-4b7e-b79f-ebdd2f31cbdb' and verification_status not in ('verified_against_standard','corrected');
-- ozon_aufenthaltszeit
update public.fields set verification_status='verified_against_standard', verification_quote='mindestens 5 bis 10 Minuten Aufenthaltszeit im Reaktionsbehälter. | Eine Verlängerung der Aufenthaltszeit auf ca. 15 bis 20 Minuten kann sinnvoll sein, um sicherzustellen, dass kein gelöstes Ozon in den Ablauf gelangt. — printed p.28', verification_note='md-verified 2026-09-05 (§4.3.3.3, printed p.28) [VC]', verified_at=now() where id='ac4ff149-a76c-41a6-bfd8-f33c3b95ac21' and verification_status not in ('verified_against_standard','corrected');
-- ct_wert
update public.fields set verification_status='verified_against_standard', verification_quote='Wesentlich für eine ausreichende Desinfektionswirkung ist die Einhaltung einer wirksamen Kombination von Ozonkonzentration (c) und Einwirkzeit ( $t$ ) ( $c t$-Konzept). Das für eine definierte Reduktion der Keimzahl einzuhaltende Produkt beider Größen ergibt den $c t$-Wert in $\mathrm{mg} \cdot \mathrm{min} \cdot \mathrm{l}^{-1}$, der für verschiedene Mikroorganismen experimentell bestimmt wurde (Merkblatt DVGW W 225). — printed p.26', verification_note='md-verified 2026-09-05 (§4.3.2, printed p.26) [VC]', verified_at=now() where id='65b159db-8e70-436d-9a23-8333da5ca7dc' and verification_status not in ('verified_against_standard','corrected');
-- ozon_aus_o2_anteil
update public.fields set verification_status='verified_against_standard', verification_quote='Anlagen für Ozonleistungen über $1 \mathrm{~kg} / \mathrm{h}$ arbeiten bei einer Spannung von ca. 10 kV und einer Frequenz von ca. 600 Hz . Für 1 kg Ozon werden etwa 10 kg Sauerstoff benötigt (bei ca. $10 \%$ bis $13 \%$ Ozon im erzeugten Gasgemisch). Pro Kubikmeter Reinsauerstoff können so ca. 150 g bis 200 g Ozon erzeugt werden. — printed p.27', verification_note='md-verified 2026-09-05 (§4.3.3.2, printed p.27) [VC]', verified_at=now() where id='7d3e5711-7c6d-46bf-9e90-e96c436c30a6' and verification_status not in ('verified_against_standard','corrected');
