-- reaktor_gasdicht
update public.fields set verification_status='verified_against_standard', verification_quote='Der Reaktionsbehälter sowie alle Durchleitungen (z. B. für Messsonden) müssen gasdicht gestaltet sein. Die Werkstoffe des Behälters und aller Einbauten müssen beständig gegen Ozon sein. Bisher wurden Behälter in Stahlbauweise sowie Betonbecken eingesetzt. — printed p.28', verification_note='md-verified 2026-09-05 (§4.3.3.3, printed p.28) [VC]', verified_at=now() where id='69adcc78-b2ed-405f-9944-f5f130908b50' and verification_status not in ('verified_against_standard','corrected');

-- ---- M205-18 · Ozonung — Restozonentfernung (thermisch/katalytisch) ----
-- restozon_abluft
update public.fields set verification_status='verified_against_standard', verification_quote='Aufgrund seiner toxischen Eigenschaften muss das im Abgas der Anlagen enthaltene Restozon vor der Ableitung ins Freie abgesaugt und gezielt auf eine Konzentration von maximal 0,02 mg/m³ vermindert werden (Merkblatt DVGW W 625). Dies kann thermisch (Erhitzen auf 350 °C über mindestens 2 Sekunden) oder katalytisch (bei 60 °C bis 80 °C) erfolgen. — printed p.28', verification_note='md-verified 2026-09-05 (§4.3.3.4, printed p.28) [VC]', verified_at=now() where id='f3924e2f-bc19-4e57-9662-6377533b6617' and verification_status not in ('verified_against_standard','corrected');
