-- verbrennung_haltezeit_s
update public.fields set verification_status='verified_against_standard', verification_quote='Aufgrund seiner toxischen Eigenschaften muss das im Abgas der Anlagen enthaltene Restozon vor der Ableitung ins Freie abgesaugt und gezielt auf eine Konzentration von maximal 0,02 mg/m³ vermindert werden (Merkblatt DVGW W 625). Dies kann thermisch (Erhitzen auf 350 °C über mindestens 2 Sekunden) oder katalytisch (bei 60 °C bis 80 °C) erfolgen. — printed p.28', verification_note='md-verified 2026-09-05 (§4.3.3.4, printed p.28) [VC]', verified_at=now() where id='1621260b-8a03-4c8a-9382-67237f2ec2af' and verification_status not in ('verified_against_standard','corrected');

-- ---- M205-19 · Ozonung — Energieeinsatz und Kosten ----
-- spez_energie_ozon
update public.fields set verification_status='verified_against_standard', verification_quote='Der spezifische Energieverbrauch der Ozonerzeugung aus Reinsauerstoff beträgt etwa 10 kWh/kg Ozon. Bei Verwendung von Luft beträgt er ca. 60 % mehr. — printed p.27', verification_note='md-verified 2026-09-05 (§4.3.3.2, printed p.27) [VC]', verified_at=now() where id='471cebdd-b739-4988-8adc-78c8173d66b0' and verification_status not in ('verified_against_standard','corrected');
-- spez_energie_anlage_ozon
update public.fields set verification_status='verified_against_standard', verification_quote='Insgesamt kann bei Einsatz von technisch reinem Sauerstoff und bei einem Einsatz von 10 mg Ozon/l Kläranlagenablauf von einem spezifischen Energieverbrauch von 0,1 kWh bis 0,15 kWh je Kubikmeter Abwasser ausgegangen werden. — printed p.28', verification_note='md-verified 2026-09-05 (§4.3.4, printed p.28) [VC]', verified_at=now() where id='8658fdad-67fa-4750-a7ef-02b16658dc63' and verification_status not in ('verified_against_standard','corrected');
-- kosten_ozon_cent_m3
update public.fields set verification_status='verified_against_standard', verification_quote='Diese lagen bei einer Ausbaugröße von 30.500 EW (max. 900 m³/h) bei 5,7 Cent/m³ (Anteil der Investition ca. 60 %); bei einer Ausbaugröße von 1,6 Mio EW (max. 200.000 m³/d) bei 1 Cent/m³ bis 2,2 Cent/m³ (je nach Verfahrensvariante; Anteil der Investition 20 % bis 30 %). Es ist zu berücksichtigen, dass diese Kostenschätzungen nicht auf die reine Desinfektionswirkung bezogen sind, sondern auch den Abbau von Spurenstoffen berücksichtigen. — printed p.28', verification_note='md-verified 2026-09-05 (§4.3.5, printed p.28) [VC]', verified_at=now() where id='296ab3f2-7200-4ee4-a1fd-064ad68b4ec1' and verification_status not in ('verified_against_standard','corrected');

-- ---- M205-20 · Ozonung — Oxidationsnebenprodukte ----
-- bromat_bildung
update public.fields set verification_status='verified_against_standard', verification_quote='Die Ozonung von bromidhaltigem Abwasser kann zur Bildung von Bromat führen, dessen Einleitung in Gewässer aufgrund seiner toxikologischen Eigenschaften grundsätzlich unerwünscht ist. Für Oberflächengewässer bestehen keine spezifischen Qualitätsnormen. Die Bromatbildung kann minimiert werden, wenn Ozon proportional zum DOC ( $<0,8 \mathrm{mg} / \mathrm{mg}$ ) dosiert wird. — printed p.29', verification_note='md-verified 2026-09-05 (§4.3.6, printed p.29) [VC] — no bromate concentration limit printed; unit µg/l is EKOWAI’s', verified_at=now() where id='73fd7590-3c34-4a91-8ef2-2a2c7466148b' and verification_status not in ('verified_against_standard','corrected');
-- ndma_bildung
update public.fields set verification_status='verified_against_standard', verification_quote='Aus organischen Aminen können durch Ozonung Nitrosamine mit krebserregender Wirkung entstehen. [...] In einem Pilotvorhaben [31] wurde die Bildung von 5 ng bis 15 ng NDMA/l beobachtet, wovon ca. 50 % in der nachfolgenden biologisch aktiven Sandfiltration wieder eliminiert wurden. — printed p.29', verification_note='md-verified 2026-09-05 (§4.3.6, printed p.29) [VC]', verified_at=now() where id='051bcf2a-82c8-4f9e-b7b1-b8c62fc8ec44' and verification_status not in ('verified_against_standard','corrected');

-- ---- M205-21 · Chlorung — Bemessung und Betrieb ----
-- chlormittel_typ
update public.fields set verification_status='verified_against_standard', verification_quote='Eine Chlorung wird in der Regel unter Verwendung von Chlorgas ( $\mathrm{Cl}_{2}$ ), Hypochloritverbindungen, z. B. Natriumhypochlorit (NaOCl, Chlorbleichlauge) oder Chlordioxid $\left(\mathrm{ClO}_{2}\right)$ durchgeführt. — printed p.29', verification_note='md-verified 2026-09-05 (§4.4.2, printed p.29) [VC]', verified_at=now() where id='0c837559-e16b-4a41-be17-7f023975823e' and verification_status not in ('verified_against_standard','corrected');
-- restchlor
update public.fields set verification_status='verified_against_standard', verification_quote='Zur Vermeidung von Beeinträchtigungen des Gewässers muss der Restchlorgehalt im Abwasser auf ein unschädliches Maß verringert werden. Die EGFischgewässerrichtlinie 2006/44/EG gibt z. B. einen Grenzwert für Restchlor von ≤ 0,005 mg/l im Gewässer vor. Daher ist eine zusätzliche Entchlorungsstufe erforderlich. — printed p.29', verification_note='md-verified 2026-09-05 (§4.4.2, printed p.29) [VC] — limit belongs to Richtlinie 2006/44/EG (external, quoted as example) — NR beyond the md', verified_at=now() where id='b2178740-0b3f-4348-8f40-fe362a83a4e4' and verification_status not in ('verified_against_standard','corrected');
-- ph_chlorung
update public.fields set verification_status='verified_against_standard', verification_quote='Je nach dem Gehalt an organischen Stoffen im Abwasser sind 1 mg bis 20 mg freies Chlor pro Liter, eine gründliche Durchmischung sowie eine Kontaktzeit von 15 bis 30 Minuten erforderlich. Eine geregelte Desinfektion ist nur dann gewährleistet, wenn ein pH-Bereich zwischen 6 und 8 eingehalten wird. — printed p.29', verification_note='md-verified 2026-09-05 (§4.4.2, printed p.29) [VC]', verified_at=now() where id='a284d43a-a8e2-49f1-be65-4173f6777425' and verification_status not in ('verified_against_standard','corrected');
-- clo2_dosis
update public.fields set verification_status='verified_against_standard', verification_quote='Bei Verwendung von gereinigtem Abwasser als Betriebswasser in Kläranlagen sind etwa 5 g bis 10 g Chlordioxid pro Kubikmeter Abwasser zur Reduktion der Fäkalindikatorbakterien um drei Zehnerpotenzen notwendig, bei sandfiltriertem Abwasser mit geringer Restverschmutzung nur 1 g/m³ bis 5 g/m³. Die erforderliche Einwirkzeit beträgt wenige Minuten. — printed p.29–30', verification_note='md-verified 2026-09-05 (§4.4.2, printed p.29–30) [VC]', verified_at=now() where id='e00e0ad1-ccd7-4ca5-94ba-59108cafb3ef' and verification_status not in ('verified_against_standard','corrected');
