update public.fields set verification_status='verified_against_standard', verification_quote='Der direkte Nachweis einer ausreichenden Desinfektionsleistung kann abschließend nur durch mikrobiologische Untersuchungen geführt werden. Wird eine regelmäßige Betriebsüberwachung durchgeführt, sind monatliche Nachweise in der Regel ausreichend. — printed p.19–20', verification_note='md-verified 2026-09-05 (§4.1.4.2, printed p.19–20) [VC]', verified_at=now() where id='af596b8c-1c43-4e5c-8934-57c5c8e2136b' and verification_status not in ('verified_against_standard','corrected');
-- gerinne_zuschaltbar
update public.fields set verification_status='verified_against_standard', verification_quote='Aus Gründen der Energieeffizienz sollte mindestens eine Anpassung an die Durchflussverhältnisse durch Zu- und Abschalten von Bestrahlungsgerinnen bzw. einzelnen Banks und durch Regelung der Strahler erfolgen [20]. | Wenn hintereinander liegende Bestrahlungsräume durchflussabhängig zu- und abgeschaltet werden, sind mindestens zwei UV-Sensoren erforderlich, einer im ständig eingeschalteten Bereich und einer im am häufigsten abgeschalteten Bereich. — printed p.18 / p.18–19', verification_note='md-verified 2026-09-05 (§4.1.3.3, printed p.18 / p.18–19) [VC]', verified_at=now() where id='dab4845b-5dac-4d1f-b5c9-f221c3a821ea' and verification_status not in ('verified_against_standard','corrected');

