-- log_reduktion
update public.fields set verification_status='verified_against_standard', verification_quote='Für die uneingeschränkte Nutzung wird eine Keimreduzierung um 6 bis 7 Log-Stufen empfohlen (bezogen auf eine Rohabwasserbelastung von 10⁷ Escherichia coli in 100 ml), für die eingeschränkte Nutzung um 4 LogStufen (bei arbeitsintensiver Bewirtschaftung) bzw. um 3 Log-Stufen (bei hoch mechanisierter Bewirtschaftung). | Die Reduktionsrate wird in der Regel in Log-Stufen oder Zehnerpotenzen angegeben und ist für die Bewertung der Leistungsfähigkeit eines Desinfektionsverfahrens wichtig. — printed p.11 / p.8', verification_note='md-verified 2026-09-05 (§3.3 + §2.1 Anmerkung, printed p.11 / p.8) [VC]', verified_at=now() where id='1047ab2b-3f51-456a-9157-6703ff584947' and verification_status not in ('verified_against_standard','corrected');

-- ---- M205-26 · Ergebniszusammenfassung, Kosten und Freigabe ----
-- kapitalkostenanteil
update public.fields set verification_status='verified_against_standard', verification_quote='Der Kapitalkostenanteil betrug dabei 63 % bis 86 %. Legt man einen ganzjährigen Betrieb zugrunde läge die Spannbreite der spezifischen Kosten bei rund 2 Cent/m³ bis 6 Cent/m³. Der Kapitalkostenanteil würde sich dabei aufgrund der größeren desinfizierten Abwassermenge auf 47 % bis 76 % reduzieren. — printed p.22', verification_note='md-verified 2026-09-05 (§4.1.5.3, printed p.22) [VC]', verified_at=now() where id='215eec87-32e8-4747-95fe-45c62fff003e' and verification_status not in ('verified_against_standard','corrected');
-- abschreibungsdauer_baulich
update public.fields set verification_status='verified_against_standard', verification_quote='Zur Abschätzung der spezifischen Kosten wurde eine Kostenvergleichsrechnung gemäß den KVR-Leitlinien [22] durchgeführt und eine Abschreibungsdauer von 25 Jahren für den bautechnischen Teil und 12,5 Jahren für den elektro- und maschinentechnischen Teil angesetzt. — printed p.22', verification_note='md-verified 2026-09-05 (§4.1.5.3, printed p.22) [VC]', verified_at=now() where id='859956da-e11c-46c1-bfa2-3feb91ae573c' and verification_status not in ('verified_against_standard','corrected');
-- abschreibungsdauer_emt
