-- ---- Section B · equations (24 rows; formula printed in words / as a range sentence) ----
-- M205-05 EQ-01: uv_dosis = uv_intensitaet * verweildauer
update public.equations set verification_status='verified_against_standard', verification_quote='Die UV-Bestrahlung, die eine Zelle im Mittel erhält, lässt sich rechnerisch als Produkt aus der mittleren Bestrahlungsstärke in $\mathrm{W} / \mathrm{m}^{2}$ und der mittleren Verweildauer in s abschätzen. — printed p.14', verification_note='md-verified 2026-09-05 (§4.1.1, printed p.14) [VC]', verified_at=now() where id='464d8a4f-72d2-4ca3-8e24-5677a57d14ce' and verification_status <> 'verified_against_standard';
-- M205-05 EQ-02: uv_dosis >= 300 AND uv_dosis <= 450
update public.equations set verification_status='verified_against_standard', verification_quote='Danach beträgt die Mindestbestrahlung etwa 300 J/m² bis 450 J/m² zur sicheren Einhaltung der Grenz- und Leitwerte der EG-Badegewässer-Richtlinie für biologisch gereinigtes Abwasser bei einer Konzentration an abfiltrierbaren Stoffen von 5 mg/l bis 20 mg/l. — printed p.16', verification_note='md-verified 2026-09-05 (§4.1.2.3, printed p.16) [VC] — printed as an empirical band („etwa“), encoded as a closed range', verified_at=now() where id='ba51e8f2-4c20-4c01-8f4d-9effcc262b37' and verification_status <> 'verified_against_standard';
-- M205-05 EQ-06: spez_strom_uv >= 30 AND spez_strom_uv <= 60
update public.equations set verification_status='verified_against_standard', verification_quote='Bei den ausgewerteten Desinfektionsanlagen bewegt sich der spezifische Stromverbrauch im Bereich von 30 Wh bis 60 Wh pro Kubikmeter behandelten Abwassers. — printed p.22', verification_note='md-verified 2026-09-05 (§4.1.5.2, printed p.22) [VC] — survey band, not a limit', verified_at=now() where id='197122ba-f723-4b27-80c1-51a972ea8e12' and verification_status <> 'verified_against_standard';
-- M205-05 EQ-12: uv_dosis >= 400 AND uv_dosis <= 700
update public.equations set verification_status='verified_against_standard', verification_quote='Eine Auswertung der Daten von verschiedenen, im Betrieb befindlichen UVAnlagen zeigt eine Schwankungsbreite für die eingestellte Mindestbestrahlung von 400 J/m² bis 600 J/m² und im Einzelfall bis zu 700 J/m² [16]. — printed p.16', verification_note='md-verified 2026-09-05 (§4.1.2.3, printed p.16) [VC] — operating-plant survey, not a normative range', verified_at=now() where id='1a5e5b28-d9c1-4a49-8c5e-9d596e000ff9' and verification_status <> 'verified_against_standard';
-- M205-06 EQ-07: spez_energie_membran >= 0.1 AND spez_energie_membran <= 0.2
update public.equations set verification_status='verified_against_standard', verification_quote='Bei einem spezifischen Energiebedarf von ca. 0,1 kWh/m³ bis 0,2 kWh/m³ Filtrat weist das Dead-end-Verfahren gegenüber dem Cross-flow-Verfahren Vorteile auf, wenn große Abwasservolumenströme mit geringer Feststoffbelastung (z. B. Kläranlagenabläufe) behandelt werden [27]. — printed p.22–23', verification_note='md-verified 2026-09-05 (§4.2.2, printed p.22–23) [VC] — Dead-End reference band; Tab. 5 prints up to 0,4 kWh/m³', verified_at=now() where id='b3126c0d-7940-413e-b3f0-b25b02ccbf38' and verification_status <> 'verified_against_standard';
-- M205-06 EQ-08: permeabilitaet = brutto_permeatfluss / transmembrandruck
update public.equations set verification_status='verified_against_standard', verification_quote='Die nachfolgend erläuterten Parameter gehen wesentlich in die Bemessung und Auslegung einer Membrandesinfektionsanlage, die Gestaltung der betrieblichen Abläufe sowie in die Beurteilung der Leistung ein: [...] - Permeabilität: Verhältnis von Brutto-Permeatfluss und Transmembrandruck in $1 /\left(\mathrm{m}^{2} \cdot \mathrm{~h} \cdot \mathrm{bar}\right)$ — printed p.23', verification_note='md-verified 2026-09-05 (§4.2.3.1, printed p.23) [VC]', verified_at=now() where id='33419052-171f-4874-94be-d63cdf0e1cfa' and verification_status <> 'verified_against_standard';
-- M205-07 EQ-03: ct_wert = ozon_konz * ozon_aufenthaltszeit
update public.equations set verification_status='verified_against_standard', verification_quote='Wesentlich für eine ausreichende Desinfektionswirkung ist die Einhaltung einer wirksamen Kombination von Ozonkonzentration (c) und Einwirkzeit ( $t$ ) ( $c t$-Konzept). Das für eine definierte Reduktion der Keimzahl einzuhaltende Produkt beider Größen ergibt den $c t$-Wert in $\mathrm{mg} \cdot \mathrm{min} \cdot \mathrm{l}^{-1}$, der für verschiedene Mikroorganismen experimentell bestimmt wurde (Merkblatt DVGW W 225). — printed p.26', verification_note='md-verified 2026-09-05 (§4.3.2, printed p.26) [VC]', verified_at=now() where id='c5762992-522f-4cf1-a58f-a46ec3ca9096' and verification_status <> 'verified_against_standard';
-- M205-07 EQ-04: ozon_pro_doc < 0.8
update public.equations set verification_status='verified_against_standard', verification_quote='Die Bromatbildung kann minimiert werden, wenn Ozon proportional zum DOC ( $<0,8 \mathrm{mg} / \mathrm{mg}$ ) dosiert wird. — printed p.29', verification_note='md-verified 2026-09-05 (§4.3.6, printed p.29) [VC]', verified_at=now() where id='5bc795dd-75f7-433c-a359-b2c1e58d7488' and verification_status <> 'verified_against_standard';
-- M205-07 EQ-05: spez_energie_ozon = 10
update public.equations set verification_status='verified_against_standard', verification_quote='Der spezifische Energieverbrauch der Ozonerzeugung aus Reinsauerstoff beträgt etwa 10 kWh/kg Ozon. Bei Verwendung von Luft beträgt er ca. 60 % mehr. — printed p.27', verification_note='md-verified 2026-09-05 (§4.3.3.2, printed p.27) [VC] — constant 10 models the Reinsauerstoff case only („etwa“); the Luft +60 % branch is not encoded', verified_at=now() where id='9fc20ef5-b655-46ee-b46f-320ab755a974' and verification_status <> 'verified_against_standard';
-- M205-08 EQ-09: clo2_dosis >= 5 AND clo2_dosis <= 10
update public.equations set verification_status='verified_against_standard', verification_quote='Bei Verwendung von gereinigtem Abwasser als Betriebswasser in Kläranlagen sind etwa 5 g bis 10 g Chlordioxid pro Kubikmeter Abwasser zur Reduktion der Fäkalindikatorbakterien um drei Zehnerpotenzen notwendig, bei sandfiltriertem Abwasser mit geringer Restverschmutzung nur 1 g/m³ bis 5 g/m³. Die erforderliche Einwirkzeit beträgt wenige Minuten. — printed p.29–30', verification_note='md-verified 2026-09-05 (§4.4.2, printed p.29–30) [VC] — the sandfiltriert branch 1–5 g/m³ is not encoded', verified_at=now() where id='0e05ac69-c6c4-460a-80b0-7664370b08ca' and verification_status <> 'verified_against_standard';
-- M205-08 EQ-10: freies_chlor >= 1 AND freies_chlor <= 20
update public.equations set verification_status='verified_against_standard', verification_quote='Je nach dem Gehalt an organischen Stoffen im Abwasser sind 1 mg bis 20 mg freies Chlor pro Liter, eine gründliche Durchmischung sowie eine Kontaktzeit von 15 bis 30 Minuten erforderlich. Eine geregelte Desinfektion ist nur dann gewährleistet, wenn ein pH-Bereich zwischen 6 und 8 eingehalten wird. — printed p.29', verification_note='md-verified 2026-09-05 (§4.4.2, printed p.29) [VC]', verified_at=now() where id='86f703b6-6348-4577-a624-029e1ce3c93b' and verification_status <> 'verified_against_standard';
-- M205-08 EQ-11: restchlor_betrieb >= 0.2
update public.equations set verification_status='verified_against_standard', verification_quote='In dem aus dem Behandlungsbecken abfließenden Abwasser muss noch ein Überschuss von freiem Chlor in der Größenordnung von 0,2 mg/l nachzuweisen sein, um die Desinfektionswirkung sicherzustellen. Dieser Restchlorgehalt muss vor Einleitung in ein Gewässer mit Hilfe einer Entchlorungsstufe entfernt werden. — printed p.29', verification_note='md-verified 2026-09-05 (§4.4.2, printed p.29) [VC] — printed „in der Größenordnung von 0,2 mg/l“, encoded as hard ≥ 0,2', verified_at=now() where id='cb540d04-9822-4941-a6e2-12a9be184c8e' and verification_status <> 'verified_against_standard';
