-- M205-19 EQ-05: spez_energie_ozon = 10
update public.equations set verification_status='verified_against_standard', verification_quote='Der spezifische Energieverbrauch der Ozonerzeugung aus Reinsauerstoff beträgt etwa 10 kWh/kg Ozon. Bei Verwendung von Luft beträgt er ca. 60 % mehr. — printed p.27', verification_note='md-verified 2026-09-05 (§4.3.3.2, printed p.27) [VC] — constant 10 models the Reinsauerstoff case only („etwa“); the Luft +60 % branch is not encoded', verified_at=now() where id='14262b5f-2a76-49f9-bddd-bac5747356cd' and verification_status <> 'verified_against_standard';
-- M205-21 EQ-09: clo2_dosis >= 5 AND clo2_dosis <= 10
update public.equations set verification_status='verified_against_standard', verification_quote='Bei Verwendung von gereinigtem Abwasser als Betriebswasser in Kläranlagen sind etwa 5 g bis 10 g Chlordioxid pro Kubikmeter Abwasser zur Reduktion der Fäkalindikatorbakterien um drei Zehnerpotenzen notwendig, bei sandfiltriertem Abwasser mit geringer Restverschmutzung nur 1 g/m³ bis 5 g/m³. Die erforderliche Einwirkzeit beträgt wenige Minuten. — printed p.29–30', verification_note='md-verified 2026-09-05 (§4.4.2, printed p.29–30) [VC] — the sandfiltriert branch 1–5 g/m³ is not encoded', verified_at=now() where id='0c258d85-0a1e-4456-b0df-12f529d11d2c' and verification_status <> 'verified_against_standard';
-- M205-21 EQ-10: freies_chlor >= 1 AND freies_chlor <= 20
update public.equations set verification_status='verified_against_standard', verification_quote='Je nach dem Gehalt an organischen Stoffen im Abwasser sind 1 mg bis 20 mg freies Chlor pro Liter, eine gründliche Durchmischung sowie eine Kontaktzeit von 15 bis 30 Minuten erforderlich. Eine geregelte Desinfektion ist nur dann gewährleistet, wenn ein pH-Bereich zwischen 6 und 8 eingehalten wird. — printed p.29', verification_note='md-verified 2026-09-05 (§4.4.2, printed p.29) [VC]', verified_at=now() where id='3f3b7237-8837-45ff-86a5-1582f7156cbd' and verification_status <> 'verified_against_standard';
-- M205-21 EQ-11: restchlor_betrieb >= 0.2
update public.equations set verification_status='verified_against_standard', verification_quote='In dem aus dem Behandlungsbecken abfließenden Abwasser muss noch ein Überschuss von freiem Chlor in der Größenordnung von 0,2 mg/l nachzuweisen sein, um die Desinfektionswirkung sicherzustellen. Dieser Restchlorgehalt muss vor Einleitung in ein Gewässer mit Hilfe einer Entchlorungsstufe entfernt werden. — printed p.29', verification_note='md-verified 2026-09-05 (§4.4.2, printed p.29) [VC] — printed „in der Größenordnung von 0,2 mg/l“, encoded as hard ≥ 0,2', verified_at=now() where id='b02ff29a-36a0-41b8-b466-0a3b701bd895' and verification_status <> 'verified_against_standard';
